/*
 * Preflight: question bank.
 *
 * 250 original practice questions. To edit a question, change its text below.
 * To add one, copy an entry, give it the next unused id, and keep exactly one
 * correct `answer` plus three `distractors` (the app shuffles the four choices).
 * `category` must be one of the seven subjects listed in CATEGORIES.
 */
window.P107 = window.P107 || {};
window.P107.CATEGORIES = ["Regulations", "Airspace & Charts", "Weather", "Airport & Radio", "Performance & Loading", "ADM & Human Factors", "Operations & Safety"];
window.P107.DIFFICULTIES = ["Foundation", "Applied", "Scenario"];
window.P107.QUESTIONS = [
  {"id": 1, "category": "Regulations", "difficulty": "Foundation", "question": "Who is directly responsible for and the final authority over a Part 107 small UAS operation?", "answer": "The designated remote pilot in command (remote PIC).", "distractors": ["The registered owner of the small UAS.", "The person manipulating the flight controls at launch.", "The visual observer assigned to scan for traffic."], "explanation": "The remote PIC must be designated before or during the flight and is responsible for regulatory compliance and safe operation.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.19", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 2, "category": "Regulations", "difficulty": "Foundation", "question": "What is the maximum total takeoff weight for an aircraft operated as a \"small unmanned aircraft\" under Part 107?", "answer": "Less than 55 pounds, including everything onboard or attached.", "distractors": ["55 pounds or less, including everything onboard or attached.", "Less than 55 pounds before payloads and attachments are added.", "Less than 75 pounds, including everything onboard or attached."], "explanation": "The aircraft, payload, and attachments together must remain below 55 pounds unless another regulatory path applies.", "source": {"label": "FAA-S-ACS-10B", "reference": "Area I, Task A — General", "url": "https://www.faa.gov/sites/faa.gov/files/training_testing/testing/acs/uas_acs.pdf"}},
  {"id": 3, "category": "Regulations", "difficulty": "Foundation", "question": "How old must an applicant be to qualify for a Remote Pilot Certificate with a small UAS rating?", "answer": "At least 16 years old.", "distractors": ["At least 14 years old.", "At least 18 years old.", "At least 21 years old."], "explanation": "Eligibility also includes English-language ability, medical fitness for safe operation, and demonstrated aeronautical knowledge.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.61", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 4, "category": "Regulations", "difficulty": "Applied", "question": "May a person without a Remote Pilot Certificate manipulate the controls during a Part 107 flight?", "answer": "Yes—under direct supervision of a remote PIC who can immediately take direct control.", "distractors": ["No; all persons at the controls must hold a Remote Pilot Certificate.", "Yes, provided a visual observer monitors the flight, even if the remote PIC cannot immediately take control.", "Yes, as long as the remote PIC remains within 25 feet of the person manipulating the controls."], "explanation": "The certificated remote PIC remains responsible and must be able to take over without delay.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.12", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 5, "category": "Regulations", "difficulty": "Foundation", "question": "Within what period must a remote pilot satisfy the aeronautical knowledge recency requirement?", "answer": "Within the previous 24 calendar months.", "distractors": ["Within the previous 12 calendar months.", "Within the preceding 24 months, counted to the exact day.", "Within the previous 36 calendar months."], "explanation": "The requirement can be met through an applicable initial knowledge test or FAA-accepted recurrent training.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.65", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 6, "category": "Regulations", "difficulty": "Scenario", "question": "A Part 107 operation causes a serious injury. How soon must the remote PIC report the safety event to the FAA?", "answer": "No later than 10 calendar days after the operation.", "distractors": ["Within 24 hours after the operation.", "No later than 5 calendar days after the operation.", "No later than 30 calendar days after the operation."], "explanation": "The reporting rule covers serious injury, loss of consciousness, and qualifying property damage.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.9", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 7, "category": "Regulations", "difficulty": "Applied", "question": "A drone damages someone else's fence during a Part 107 flight, and the repairs cost $600. Must the remote PIC report the event to the FAA?", "answer": "Yes, assuming the operation caused the damage.", "distractors": ["No; the threshold is $1,000 in repairs.", "No; that damage is reported to local law enforcement, not the FAA.", "Yes, but only if someone was also injured in the operation."], "explanation": "Damage to property other than the small UAS is reportable when repair cost or fair-market value in a total loss exceeds $500.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.9(b)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 8, "category": "Regulations", "difficulty": "Foundation", "question": "What is the maximum groundspeed allowed under standard Part 107 operating limits?", "answer": "87 knots, or 100 miles per hour.", "distractors": ["76 knots, or 87 miles per hour.", "100 knots, or approximately 115 miles per hour.", "120 knots, or approximately 138 miles per hour."], "explanation": "This is groundspeed—not indicated airspeed—and exceeding it requires an applicable waiver.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.51(a)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 9, "category": "Regulations", "difficulty": "Applied", "question": "When may a Part 107 drone fly higher than 400 feet above ground level without a waiver?", "answer": "When it stays within 400 feet of a structure and no more than 400 feet above that structure’s uppermost limit.", "distractors": ["When it stays within 1,000 feet horizontally of a structure, regardless of height above it.", "When it remains directly over a structure and stays no more than 500 feet above the structure.", "When the owner of the structure beneath the flight authorizes the operation above 400 feet."], "explanation": "Both the horizontal radius and the height-above-structure conditions must be met.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.51(b)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 10, "category": "Regulations", "difficulty": "Foundation", "question": "What minimum flight visibility is required at the control station under standard Part 107 limits?", "answer": "At least 3 statute miles.", "distractors": ["At least 1 statute mile.", "At least 3 nautical miles.", "At least 5 statute miles."], "explanation": "Visibility is evaluated from the control station using the regulation's day or night definition.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.51(c)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 11, "category": "Regulations", "difficulty": "Foundation", "question": "What are the standard Part 107 cloud-clearance minimums?", "answer": "At least 500 feet below and 2,000 feet horizontally from clouds.", "distractors": ["At least 1,000 feet below and 2,000 feet horizontally from clouds.", "At least 500 feet below and 1,000 feet horizontally from clouds.", "At least 2,000 feet below and 500 feet horizontally from clouds."], "explanation": "Both clearances apply unless the operation is conducted under an applicable waiver.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.51(d)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 12, "category": "Regulations", "difficulty": "Applied", "question": "What two core conditions allow routine Part 107 operations at night?", "answer": "The remote PIC has completed qualifying updated knowledge testing or training, and the aircraft has anti-collision lighting visible for at least 3 statute miles.", "distractors": ["The remote PIC holds a current remote pilot certificate, and the aircraft displays steady position lights visible for at least 3 statute miles.", "The remote PIC has completed updated training, and the aircraft carries a steady white light visible for at least 1 statute mile.", "A visual observer is used throughout, and the aircraft carries a flashing light visible for at least 5 statute miles."], "explanation": "The light must flash fast enough to avoid collision; intensity may be reduced for safety but the light may not be extinguished.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.29(a)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 13, "category": "Regulations", "difficulty": "Scenario", "question": "Anti-collision lighting creates glare that makes a night operation less safe. What may the remote PIC do?", "answer": "Reduce the light’s intensity, but not extinguish it, if doing so is in the interest of safety.", "distractors": ["Extinguish the anti-collision light when glare washes out the camera image.", "Switch the anti-collision light from flashing to a steady mode to cut the glare.", "Cover the light while the aircraft remains within visual line of sight of the control station."], "explanation": "The rule permits a safety-based reduction in intensity while the anti-collision light stays lit and flashing.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.29(a)(2)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 14, "category": "Regulations", "difficulty": "Applied", "question": "What vision aid is permitted while maintaining required visual line of sight?", "answer": "Corrective lenses; binoculars or similar vision-enhancing devices do not satisfy continuous VLOS.", "distractors": ["Binoculars may be used continuously as the primary means of maintaining visual line of sight.", "First-person-view goggles alone satisfy visual line of sight when the video link is reliable.", "A telescope operated by the visual observer satisfies continuous visual line of sight."], "explanation": "The crew must be able to see the aircraft throughout flight with unaided vision other than corrective lenses.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.31", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 15, "category": "Regulations", "difficulty": "Scenario", "question": "Can one person act as remote PIC for two drones operating at the same time under standard Part 107 rules?", "answer": "No.", "distractors": ["No, unless both stay in sight.", "Yes, if one is fully automated.", "Yes, if one weighs 0.55 pounds or less."], "explanation": "A person may not manipulate controls, act as remote PIC, or serve as visual observer for more than one operation at a time.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.35", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 16, "category": "Regulations", "difficulty": "Foundation", "question": "Which aircraft has right of way in an encounter: a small UAS or any manned aircraft?", "answer": "The manned aircraft; the small UAS must yield and remain well clear.", "distractors": ["The small UAS has right of way while it remains below 400 feet AGL.", "Whichever aircraft reaches the conflict point first.", "The aircraft approaching from the left has right of way."], "explanation": "The small UAS may not pass over, under, or ahead of the other aircraft unless well clear.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.37", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 17, "category": "Regulations", "difficulty": "Applied", "question": "May a remote pilot drop an object from a drone during a Part 107 operation?", "answer": "Only if doing so does not create an undue hazard to people or property.", "distractors": ["Only if the operation is covered by a waiver issued in advance.", "Only if the object being released weighs less than 0.55 pounds.", "Only if the owner of the property beneath the flight gives permission."], "explanation": "Part 107 prohibits dropping that creates an undue hazard, not every release of an object.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.23(b)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 18, "category": "Regulations", "difficulty": "Scenario", "question": "During an in-flight emergency requiring immediate action, may the remote PIC deviate from Part 107?", "answer": "Yes, only to the extent necessary to meet the emergency.", "distractors": ["No; deviation requires a waiver obtained before the flight.", "Yes, and the deviation may continue for the rest of the flight.", "Yes, after air traffic control approves the deviation."], "explanation": "Section 107.21 allows deviation from the rules of Part 107 only as far as the emergency requires; a written report is required if the Administrator requests one.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.21", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 19, "category": "Regulations", "difficulty": "Applied", "question": "What must an applicant demonstrate to obtain a Part 107 waiver?", "answer": "That the proposed operation can be conducted safely under the requested waiver’s terms.", "distractors": ["That the operation will produce a substantial economic or public benefit.", "That the remote PIC holds at least 100 hours of flight experience and liability insurance.", "That the remote PIC has coordinated the operation with the nearest air traffic control facility."], "explanation": "The request needs a complete operational description and a safety justification; approval is not automatic.", "source": {"label": "FAA Part 107 Waivers", "reference": "§§ 107.200–107.205", "url": "https://www.faa.gov/uas/commercial_operators/part_107_waivers"}},
  {"id": 20, "category": "Regulations", "difficulty": "Foundation", "question": "What are the three normal ways a drone pilot can comply with Remote ID?", "answer": "Use a Standard Remote ID drone, attach a Remote ID broadcast module, or fly a non-equipped drone inside a FRIA under its conditions.", "distractors": ["Use ADS-B Out, remain below 400 feet AGL, or obtain a LAANC authorization before the flight.", "Fly in Class G airspace, use a visual observer, or keep the drone within 500 feet of the control station.", "File a NOTAM, monitor the local CTAF, or carry the aircraft's registration certificate."], "explanation": "Most drones that must be registered must also comply with Remote ID; each path has its own operating conditions.", "source": {"label": "FAA Remote ID", "reference": "Remote ID compliance methods", "url": "https://www.faa.gov/uas/getting_started/remote_id"}},
  {"id": 21, "category": "Airspace & Charts", "difficulty": "Foundation", "question": "Which controlled-airspace classes generally require prior ATC authorization for Part 107 operations?", "answer": "Class B, C, and D, plus Class E surface areas designated for an airport.", "distractors": ["All Class E airspace, including areas that begin at 700 or 1,200 feet AGL.", "Class B, C, and D, but not Class E surface areas designated for an airport.", "Class B, C, and D, plus any Class G airspace within five miles of an airport."], "explanation": "The authorization requirement applies within the lateral boundaries of those controlled surface areas.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.41", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 22, "category": "Airspace & Charts", "difficulty": "Foundation", "question": "What airspace class normally begins at the surface and extends to 10,000 feet MSL around the nation's busiest airports?", "answer": "Class B airspace.", "distractors": ["Class C airspace.", "Class D airspace.", "Class E airspace."], "explanation": "Its shape and floors vary by location and are charted in layers, often compared to an upside-down wedding cake.", "source": {"label": "FAA Remote Pilot Study Guide", "reference": "Chapter 2 — Class B Airspace", "url": "https://www.faa.gov/sites/faa.gov/files/regulations_policies/handbooks_manuals/aviation/remote_pilot_study_guide.pdf"}},
  {"id": 23, "category": "Airspace & Charts", "difficulty": "Foundation", "question": "What chart color and line style depict the outer boundaries of Class B airspace on a sectional?", "answer": "Solid blue lines.", "distractors": ["Dashed blue lines.", "Solid magenta lines.", "Shaded blue vignettes."], "explanation": "Blue floor-and-ceiling numbers inside the boundary identify the vertical limits in hundreds of feet MSL.", "source": {"label": "FAA Remote Pilot Study Guide", "reference": "Chapter 2 — Aeronautical charts", "url": "https://www.faa.gov/sites/faa.gov/files/regulations_policies/handbooks_manuals/aviation/remote_pilot_study_guide.pdf"}},
  {"id": 24, "category": "Airspace & Charts", "difficulty": "Foundation", "question": "What chart color and line style depict Class C airspace?", "answer": "Solid magenta lines.", "distractors": ["Solid blue lines.", "Dashed magenta lines.", "Dashed blue lines."], "explanation": "Class C typically has a surface core and an outer shelf, but pilots must read the charted limits for the location.", "source": {"label": "FAA Remote Pilot Study Guide", "reference": "Chapter 2 — Class C Airspace", "url": "https://www.faa.gov/sites/faa.gov/files/regulations_policies/handbooks_manuals/aviation/remote_pilot_study_guide.pdf"}},
  {"id": 25, "category": "Airspace & Charts", "difficulty": "Foundation", "question": "What sectional-chart symbol normally marks a Class D surface boundary?", "answer": "A dashed blue line.", "distractors": ["A dashed magenta line.", "A solid blue line.", "A shaded magenta vignette."], "explanation": "The top is commonly shown by a boxed altitude in hundreds of feet MSL, but charted exceptions must be checked.", "source": {"label": "FAA Remote Pilot Study Guide", "reference": "Chapter 2 — Class D Airspace", "url": "https://www.faa.gov/sites/faa.gov/files/regulations_policies/handbooks_manuals/aviation/remote_pilot_study_guide.pdf"}},
  {"id": 26, "category": "Airspace & Charts", "difficulty": "Foundation", "question": "What does a dashed magenta boundary on a sectional normally indicate?", "answer": "Class E airspace beginning at the surface.", "distractors": ["Class D airspace extending upward from the surface.", "The outer shelf of Class C airspace.", "Class E airspace with a floor at 700 feet AGL."], "explanation": "A dashed magenta line marks a Class E surface area. Because it is designated for an airport, a Part 107 operation inside its lateral boundary requires prior ATC authorization.", "source": {"label": "FAA Remote Pilot Study Guide", "reference": "Chapter 2 — Class E Airspace", "url": "https://www.faa.gov/sites/faa.gov/files/regulations_policies/handbooks_manuals/aviation/remote_pilot_study_guide.pdf"}},
  {"id": 27, "category": "Airspace & Charts", "difficulty": "Applied", "question": "What does a shaded magenta vignette around an airport indicate about the floor of Class E airspace?", "answer": "Class E begins at 700 feet AGL inside the vignette.", "distractors": ["Class E begins at 1,200 feet AGL inside the vignette.", "Class E extends down to the surface inside the vignette.", "Class E begins at 700 feet MSL inside the vignette."], "explanation": "The shaded magenta vignette marks a Class E floor of 700 feet AGL. Below that floor, the airspace is generally Class G unless another surface area is charted.", "source": {"label": "FAA Remote Pilot Study Guide", "reference": "Chapter 2 — Class E floor depictions", "url": "https://www.faa.gov/sites/faa.gov/files/regulations_policies/handbooks_manuals/aviation/remote_pilot_study_guide.pdf"}},
  {"id": 28, "category": "Airspace & Charts", "difficulty": "Applied", "question": "What does a shaded blue vignette indicate about the floor of Class E airspace?", "answer": "Class E begins at 1,200 feet AGL inside the vignette.", "distractors": ["Class E begins at 700 feet AGL inside the vignette.", "Class E begins at 1,200 feet MSL inside the vignette.", "Class E begins at 18,000 feet MSL inside the vignette."], "explanation": "The blue vignette marks the higher Class E floor of 1,200 feet AGL; the magenta vignette marks the lower 700-foot AGL floor.", "source": {"label": "FAA Remote Pilot Study Guide", "reference": "Chapter 2 — Class E floor depictions", "url": "https://www.faa.gov/sites/faa.gov/files/regulations_policies/handbooks_manuals/aviation/remote_pilot_study_guide.pdf"}},
  {"id": 29, "category": "Airspace & Charts", "difficulty": "Scenario", "question": "You are operating in Class G airspace at the surface, with Class E airspace beginning at 700 feet AGL overhead. You will stay at 300 feet AGL. Does 14 CFR 107.41 require ATC authorization solely because of the Class E airspace above you?", "answer": "No.", "distractors": ["Yes; Class E overhead extends ATC authority to the surface.", "Yes; Class E within 500 feet above you requires authorization.", "No; the site lies beyond five statute miles of an airport."], "explanation": "At 300 feet AGL the aircraft stays in Class G airspace, so 107.41 is not triggered. Other restrictions, airspace notices, and Part 107 rules still apply.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.41", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 30, "category": "Airspace & Charts", "difficulty": "Applied", "question": "What is LAANC used for by Part 107 pilots?", "answer": "Requesting near-real-time or further-coordinated authorization to operate in eligible controlled airspace.", "distractors": ["Obtaining an official preflight weather briefing for a small UAS mission.", "Submitting a request to waive a standard Part 107 operating limitation, such as the restriction on flight over people.", "Registering a small UAS and activating its Remote ID broadcast."], "explanation": "LAANC returns authorization up to the charted ceiling in participating controlled airspace, with further coordination available for other requests. The approval does not replace any other applicable rule or authorization condition.", "source": {"label": "FAA Part 107 Airspace Authorizations", "reference": "LAANC authorization guidance", "url": "https://www.faa.gov/uas/commercial_operators/part_107_airspace_authorizations"}},
  {"id": 31, "category": "Airspace & Charts", "difficulty": "Foundation", "question": "May you enter a prohibited area with a small UAS merely because you are below 400 feet AGL?", "answer": "No.", "distractors": ["Yes; flight below 400 feet AGL is exempt from the restriction.", "No; entry requires the landowner's written permission.", "Yes; the area is open whenever no Temporary Flight Restriction is active."], "explanation": "Operations in prohibited or restricted areas require permission from the using or controlling agency, as appropriate.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.45", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 32, "category": "Airspace & Charts", "difficulty": "Applied", "question": "What is the key operational difference between a restricted area and a military operations area (MOA)?", "answer": "A Part 107 pilot may not enter a restricted area without agency permission. A MOA is nonregulatory; it does not prohibit VFR entry, but pilots should check its status and use extreme caution.", "distractors": ["Both are nonregulatory advisory areas. A Part 107 pilot may enter either one without permission after checking its status and using extra caution.", "A restricted area may be entered without permission whenever it is not active, while an MOA is closed to VFR traffic for the entire period it is in use.", "An MOA requires prior ATC authorization before entry. A restricted area may be crossed without permission as long as the aircraft stays below 400 feet AGL."], "explanation": "Restricted areas are regulatory: Section 107.45 requires permission from the using or controlling agency, and it creates no exception for periods when the area is inactive. An MOA is nonregulatory, so VFR entry is not prohibited, but activity can change frequently and may involve fast military traffic.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "AIM §§ 3-4-3 and 3-4-5; 14 CFR § 107.45", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap3_section_4.html"}},
  {"id": 33, "category": "Airspace & Charts", "difficulty": "Foundation", "question": "What is a Temporary Flight Restriction (TFR)?", "answer": "A short-term restriction issued by NOTAM for a defined area, time, and purpose.", "distractors": ["Permanently designated special-use airspace charted around large metropolitan airports.", "An advisory area that recommends caution but imposes no operating restriction.", "A standing 30-nautical-mile restriction that is continuously in effect around towered airports."], "explanation": "A TFR restricts flight in a defined area for a limited period and is published by NOTAM. Common causes include disasters, major events, VIP movement, wildfire response, or space operations, so pilots must check current notices.", "source": {"label": "FAA-S-ACS-10B", "reference": "Area II — Flight restrictions and NOTAMs", "url": "https://www.faa.gov/sites/faa.gov/files/training_testing/testing/acs/uas_acs.pdf"}},
  {"id": 34, "category": "Airspace & Charts", "difficulty": "Applied", "question": "On a sectional, an obstacle is labeled with two numbers, the second one in parentheses. What do those numbers normally represent?", "answer": "The top number is the obstacle elevation MSL; the parenthetical number is its height AGL.", "distractors": ["The top number is the obstacle's height AGL; the parenthetical number is its elevation MSL.", "The top number is the obstacle-top elevation MSL, and the parenthetical number is the obstacle-base elevation MSL.", "The top number is the obstacle's height above the airport, and the parenthetical number is its distance from that airport."], "explanation": "Both matter: MSL supports chart comparison, while AGL shows the structure's height above local terrain.", "source": {"label": "FAA Remote Pilot Study Guide", "reference": "Chapter 11 — Obstructions", "url": "https://www.faa.gov/sites/faa.gov/files/regulations_policies/handbooks_manuals/aviation/remote_pilot_study_guide.pdf"}},
  {"id": 35, "category": "Airspace & Charts", "difficulty": "Applied", "question": "What does a sectional chart's Maximum Elevation Figure (MEF) communicate?", "answer": "The elevation of the highest terrain or obstacle in that quadrangle, with charting allowance, expressed in hundreds of feet MSL.", "distractors": ["A minimum safe altitude that guarantees regulatory obstacle clearance anywhere inside the quadrangle, in hundreds of feet MSL.", "The height above ground of the highest airport in the quadrangle, expressed in hundreds of feet.", "The height of the tallest man-made obstruction, with terrain and the charting allowance excluded."], "explanation": "MEF is a planning aid, not a guarantee of obstacle clearance and not a substitute for local reconnaissance.", "source": {"label": "FAA Remote Pilot Study Guide", "reference": "Chapter 2 — Sectional chart features", "url": "https://www.faa.gov/sites/faa.gov/files/regulations_policies/handbooks_manuals/aviation/remote_pilot_study_guide.pdf"}},
  {"id": 36, "category": "Airspace & Charts", "difficulty": "Scenario", "question": "A sectional shows a tower as 1,549 MSL (500 AGL). What is the approximate ground elevation at the tower?", "answer": "About 1,049 feet MSL.", "distractors": ["About 500 feet MSL.", "About 1,549 feet MSL.", "About 2,049 feet MSL."], "explanation": "Subtract the obstacle height AGL from its top elevation MSL: 1,549 - 500 = 1,049.", "source": {"label": "FAA Remote Pilot Study Guide", "reference": "Chapter 11 — Obstruction elevations", "url": "https://www.faa.gov/sites/faa.gov/files/regulations_policies/handbooks_manuals/aviation/remote_pilot_study_guide.pdf"}},
  {"id": 37, "category": "Weather", "difficulty": "Foundation", "question": "What does a METAR provide?", "answer": "A routine observation of current surface weather at an airport or reporting station.", "distractors": ["A forecast of the weather expected at the airport during a stated future valid period.", "A pilot's in-flight report of turbulence, icing, and cloud tops.", "A time-sensitive notice about airport closures and airspace restrictions."], "explanation": "A METAR is the routine, scheduled observation of conditions at the station; a SPECI is a special, unscheduled report issued when significant weather criteria are met.", "source": {"label": "NWS METAR/TAF Key", "reference": "METAR message type", "url": "https://www.weather.gov/media/epz/aviation/TAF_Card.pdf"}},
  {"id": 38, "category": "Weather", "difficulty": "Foundation", "question": "What does a TAF provide?", "answer": "A coded forecast of weather expected near an airport during a stated valid period.", "distractors": ["A routine observation of the surface weather already occurring at the reporting station.", "A nationwide outlook for en route turbulence and icing hazards.", "A pilot's report of the weather actually encountered during a flight."], "explanation": "A TAF forecasts conditions expected in the vicinity of the airport during its valid period. Verify the issue time and valid period; TAF times are in UTC (Zulu).", "source": {"label": "NWS METAR/TAF Key", "reference": "TAF message type and valid period", "url": "https://www.weather.gov/media/epz/aviation/TAF_Card.pdf"}},
  {"id": 39, "category": "Weather", "difficulty": "Applied", "question": "Decode the METAR wind group \"22015G25KT.\"", "answer": "Wind from 220° true at 15 knots, gusting to 25 knots.", "distractors": ["Wind blowing toward 220° true at 15 knots, gusting to 25 knots.", "Wind from 220° true at 25 knots, gusting to 15 knots.", "Wind from 220° magnetic at 15 knots, with gusts to 25 knots."], "explanation": "METAR wind direction is referenced to true north; the G value is the peak gust speed.", "source": {"label": "NWS METAR/TAF Key", "reference": "Wind group", "url": "https://www.weather.gov/media/epz/aviation/TAF_Card.pdf"}},
  {"id": 40, "category": "Weather", "difficulty": "Applied", "question": "What does \"00000KT\" mean in a METAR?", "answer": "Calm wind.", "distractors": ["Variable wind at 5 knots.", "Wind from true north at 10 knots.", "Unknown direction, gusts to 10 knots."], "explanation": "Variable direction is coded VRB, while calm is reported as all zeros.", "source": {"label": "NWS METAR/TAF Key", "reference": "Wind group", "url": "https://www.weather.gov/media/epz/aviation/TAF_Card.pdf"}},
  {"id": 41, "category": "Weather", "difficulty": "Applied", "question": "Decode \"3/4SM\" in a METAR.", "answer": "Three-quarters of a statute mile visibility.", "distractors": ["Three point four statute miles visibility.", "Three-quarters of a nautical mile visibility.", "Three statute miles with four-mile directional variation."], "explanation": "Visibility in a METAR is given in statute miles, so 3/4SM is three-quarters of a statute mile. Part 107 normally requires at least 3 statute miles of flight visibility from the control station.", "source": {"label": "NWS METAR/TAF Key", "reference": "Prevailing visibility", "url": "https://www.weather.gov/media/epz/aviation/TAF_Card.pdf"}},
  {"id": 42, "category": "Weather", "difficulty": "Applied", "question": "Decode the cloud group \"BKN015.\"", "answer": "A broken cloud layer with a base 1,500 feet above ground level.", "distractors": ["A broken cloud layer with a base 15,000 feet above ground level.", "A broken cloud layer with a base 1,500 feet above mean sea level.", "An overcast cloud layer with a base 1,500 feet above ground level."], "explanation": "BKN and OVC layers constitute a ceiling; the three digits give hundreds of feet AGL.", "source": {"label": "NWS METAR/TAF Key", "reference": "Sky condition group", "url": "https://www.weather.gov/media/epz/aviation/TAF_Card.pdf"}},
  {"id": 43, "category": "Weather", "difficulty": "Foundation", "question": "Which reported sky conditions constitute a ceiling?", "answer": "The lowest broken (BKN), overcast (OVC), or vertical visibility (VV) layer.", "distractors": ["The lowest scattered (SCT), broken (BKN), or overcast (OVC) layer reported.", "The highest broken (BKN) or overcast (OVC) layer in the observation.", "Any few (FEW) layer reported below 1,000 feet above ground level."], "explanation": "The ceiling is the height of the lowest BKN, OVC, or VV layer. Few and scattered layers are not ceilings, though they may still affect a mission.", "source": {"label": "NWS METAR/TAF Key", "reference": "Ceiling and sky cover", "url": "https://www.weather.gov/media/epz/aviation/TAF_Card.pdf"}},
  {"id": 44, "category": "Weather", "difficulty": "Applied", "question": "Decode the temperature/dew-point group \"18/16.\"", "answer": "Temperature 18°C and dew point 16°C.", "distractors": ["Temperature 18°C and dew point minus 16°C.", "Temperature 16°C and dew point 18°C.", "Temperature 18°F and dew point 16°F."], "explanation": "A small temperature/dew-point spread indicates air near saturation and increased potential for fog or low cloud.", "source": {"label": "NWS METAR/TAF Key", "reference": "Temperature/dew-point group", "url": "https://www.weather.gov/media/epz/aviation/TAF_Card.pdf"}},
  {"id": 45, "category": "Weather", "difficulty": "Applied", "question": "What does \"A2992\" mean in a METAR?", "answer": "Altimeter setting 29.92 inches of mercury.", "distractors": ["Atmospheric pressure 2,992 hectopascals.", "Altimeter setting 29.92 millibars.", "Field elevation 2,992 feet MSL."], "explanation": "The A prefix is followed by four digits representing inches of mercury to the hundredth.", "source": {"label": "NWS METAR/TAF Key", "reference": "Altimeter setting", "url": "https://www.weather.gov/media/epz/aviation/TAF_Card.pdf"}},
  {"id": 46, "category": "Weather", "difficulty": "Foundation", "question": "What three ingredients are required for a thunderstorm to form?", "answer": "Moisture, unstable air, and a lifting action.", "distractors": ["Moisture, stable air, and a sustained sinking motion.", "Dry air, instability, and a lifting action.", "Moisture, a temperature inversion, and low-level wind shear."], "explanation": "Removing any one of the three prevents thunderstorm development.", "source": {"label": "FAA Aviation Weather Handbook", "reference": "Thunderstorm formation", "url": "https://www.faa.gov/sites/faa.gov/files/FAA-H-8083-28B.pdf"}},
  {"id": 47, "category": "Weather", "difficulty": "Scenario", "question": "A mature thunderstorm is near the site but no rain is falling at your launch point. What is the safest decision?", "answer": "Do not launch; remain well clear and wait for the hazard to pass.", "distractors": ["Launch now; the site stays safe until precipitation reaches it.", "Launch below 200 feet AGL, where thunderstorm hazards do not reach.", "Do not launch unless you can keep the storm in visual line of sight."], "explanation": "Thunderstorms can produce lightning, hail, severe turbulence, gust fronts, and wind shear well beyond visible precipitation.", "source": {"label": "FAA Aviation Weather Handbook", "reference": "Thunderstorm hazards", "url": "https://www.faa.gov/sites/faa.gov/files/FAA-H-8083-28B.pdf"}},
  {"id": 48, "category": "Weather", "difficulty": "Foundation", "question": "How does stable air typically differ from unstable air?", "answer": "Stable air favors smooth conditions, stratiform clouds, and poorer visibility; unstable air favors turbulence, vertical clouds, showers, and generally better visibility outside precipitation.", "distractors": ["Stable air favors turbulence, cumuliform clouds, and good visibility outside showers; unstable air favors smooth flight, stratus layers, and trapped haze.", "Stable air supports strong vertical currents, building cumulus, and showers, while unstable air suppresses vertical motion and holds cloud in flat layers.", "Stability describes only how steady the surface wind stays through the day, so cloud type, turbulence, and visibility are unrelated to it."], "explanation": "Stability describes the atmosphere's resistance to vertical motion, which is why stable air tends to give smooth flight, layered cloud, and trapped haze, while unstable air gives turbulence, vertical cloud growth, and showers.", "source": {"label": "FAA Aviation Weather Handbook", "reference": "Atmospheric stability", "url": "https://www.faa.gov/sites/faa.gov/files/FAA-H-8083-28B.pdf"}},
  {"id": 49, "category": "Weather", "difficulty": "Applied", "question": "What weather change is commonly associated with a passing cold front?", "answer": "A wind shift, temperature drop, pressure change, and potentially showery or convective weather.", "distractors": ["A gradual temperature rise, steady pressure, and widespread stratiform cloud with light, continuous rain.", "Little change in wind or pressure, with skies gradually clearing as the front passes.", "Warmer air behind the front, a rising dew point, and slowly building fair-weather cumulus."], "explanation": "Cold fronts lift warmer air rapidly, so their weather can be more abrupt than that of a typical warm front.", "source": {"label": "FAA Aviation Weather Handbook", "reference": "Fronts and air masses", "url": "https://www.faa.gov/sites/faa.gov/files/FAA-H-8083-28B.pdf"}},
  {"id": 50, "category": "Weather", "difficulty": "Applied", "question": "Why is a temperature inversion important to a drone pilot?", "answer": "It can trap haze, smoke, and moisture near the surface, reducing visibility despite otherwise calm conditions.", "distractors": ["It promotes vigorous vertical mixing through the lowest few thousand feet, which quickly clears haze away from the surface.", "It produces strong, gusty surface winds that scatter smoke and moisture away from the site.", "It is a layer in which temperature falls unusually fast with height, creating strong instability."], "explanation": "An inversion is a layer in which temperature increases with altitude. That strong stability suppresses mixing, so haze, smoke, and moisture collect beneath it and cut visibility.", "source": {"label": "FAA Aviation Weather Handbook", "reference": "Temperature inversions and visibility", "url": "https://www.faa.gov/sites/faa.gov/files/FAA-H-8083-28B.pdf"}},
  {"id": 51, "category": "Weather", "difficulty": "Scenario", "question": "Surface wind is light, but the forecast calls for a sharp change in wind speed and direction just above the trees. What hazard should concern you?", "answer": "Low-level wind shear.", "distractors": ["High density altitude.", "Radiation fog above the tree line.", "Altimeter-setting error from the wind aloft."], "explanation": "A rapid wind change over a short distance can cause abrupt attitude, groundspeed, and control changes—especially near takeoff and landing.", "source": {"label": "FAA Aviation Weather Handbook", "reference": "Wind shear", "url": "https://www.faa.gov/sites/faa.gov/files/FAA-H-8083-28B.pdf"}},
  {"id": 52, "category": "Weather", "difficulty": "Applied", "question": "Which combination produces the highest density altitude?", "answer": "High elevation, high temperature, low pressure, and high humidity.", "distractors": ["Low elevation, low temperature, high pressure, and low humidity.", "High elevation, very low temperature, high pressure, and dry air.", "Sea-level elevation, low temperature, high pressure, and low humidity."], "explanation": "High density altitude means lower air density, reducing propeller efficiency and aircraft performance.", "source": {"label": "FAA Pilot’s Handbook of Aeronautical Knowledge", "reference": "Aircraft performance and density altitude", "url": "https://www.faa.gov/regulations_policies/handbooks_manuals/aviation/phak"}},
  {"id": 53, "category": "Weather", "difficulty": "Foundation", "question": "What conditions favor radiation fog?", "answer": "Clear skies, light wind, moist air, and nighttime surface cooling.", "distractors": ["Warm, moist air moving over a colder surface in a moderate wind.", "Moist, unstable air forced rapidly up a mountain slope.", "Overcast daylight conditions, dry air, and strong turbulent wind."], "explanation": "Strong wind tends to mix the air, while calm to light wind supports cooling and saturation near the surface.", "source": {"label": "FAA Aviation Weather Handbook", "reference": "Fog formation", "url": "https://www.faa.gov/sites/faa.gov/files/FAA-H-8083-28B.pdf"}},
  {"id": 54, "category": "Weather", "difficulty": "Applied", "question": "In a TAF, how does \"FM\" differ from \"TEMPO\"?", "answer": "FM starts a new prevailing condition at a specified time; TEMPO describes temporary fluctuations during a stated period.", "distractors": ["FM describes a brief fluctuation lasting less than one hour; TEMPO starts a new prevailing condition.", "FM signals a gradual change spread over about two hours, while TEMPO sets the prevailing conditions for the rest of the forecast.", "FM and TEMPO both indicate the same abrupt, lasting change in prevailing conditions."], "explanation": "A TEMPO condition is expected for less than one hour at a time and less than half of the indicated period in total.", "source": {"label": "NWS METAR/TAF Key", "reference": "TAF change groups", "url": "https://www.weather.gov/media/epz/aviation/TAF_Card.pdf"}},
  {"id": 55, "category": "Airport & Radio", "difficulty": "Foundation", "question": "What is the purpose of a Common Traffic Advisory Frequency (CTAF)?", "answer": "To let pilots exchange traffic information and position reports at or near an airport, especially when no tower is operating.", "distractors": ["To request an airspace authorization from air traffic control before operating anywhere near the airport.", "To receive automated airport weather observations at the field without the pilot transmitting anything.", "To let a tower controller sequence arriving traffic into the pattern after the tower closes for the night."], "explanation": "Monitoring CTAF helps a remote crew build traffic awareness, but radio calls never replace visual scanning and yielding.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "AIM § 4-1-9 — Traffic advisory practices", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap4_section_1.html"}},
  {"id": 56, "category": "Airport & Radio", "difficulty": "Applied", "question": "A runway is numbered 27. Approximately which magnetic direction does it point?", "answer": "270°, or west.", "distractors": ["027°, or northeast.", "090°, or east.", "180°, or south."], "explanation": "Runway numbers are the magnetic heading rounded to the nearest 10 degrees with the final zero omitted.", "source": {"label": "FAA Pilot’s Handbook of Aeronautical Knowledge", "reference": "Airport operations — runway markings", "url": "https://www.faa.gov/regulations_policies/handbooks_manuals/aviation/phak"}},
  {"id": 57, "category": "Airport & Radio", "difficulty": "Foundation", "question": "Unless airport indicators or published information show otherwise, which direction do standard traffic-pattern turns use?", "answer": "Left turns.", "distractors": ["Right turns.", "Alternating turns.", "Turns into the wind."], "explanation": "Right traffic is identified by traffic-pattern indicators or chart information such as \"RP\" followed by a runway number.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "Traffic patterns", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap4_section_3.html"}},
  {"id": 58, "category": "Airport & Radio", "difficulty": "Applied", "question": "Which end of a windsock points into the wind?", "answer": "The large, open end.", "distractors": ["The narrow, trailing end.", "Neither end—it shows speed, not direction.", "The end nearest the active runway."], "explanation": "The narrow end streams downwind, helping determine the wind direction and likely runway in use.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "Visual indicators at airports", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap4_section_3.html"}},
  {"id": 59, "category": "Airport & Radio", "difficulty": "Applied", "question": "What does the small end of an airport tetrahedron indicate?", "answer": "The direction of landing and takeoff.", "distractors": ["The direction from which the wind is blowing.", "The direction opposite landing and takeoff.", "The preferred direction for ground taxi."], "explanation": "A tetrahedron is not a wind indicator, and tower instructions supersede it when the tower is operating.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "Landing direction indicator", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap4_section_3.html"}},
  {"id": 60, "category": "Airport & Radio", "difficulty": "Foundation", "question": "What information can a segmented circle system provide?", "answer": "Wind direction, landing direction, runway alignment, and traffic-pattern direction.", "distractors": ["Runway length, airport elevation, available fuel, and lighting intensity.", "Controlled-airspace boundaries, radio frequencies, and cloud-clearance minimums.", "Taxi routing from the ramp to each runway threshold and the run-up area locations."], "explanation": "Its components help pilots interpret airport operations when a control tower is not operating.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "Segmented circle system", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap4_section_3.html"}},
  {"id": 61, "category": "Airport & Radio", "difficulty": "Applied", "question": "What information should a concise self-announce broadcast at a non-towered airport include?", "answer": "The correct airport name, aircraft type and call sign, position and altitude as applicable, and intentions; repeat the airport name at the end.", "distractors": ["The aircraft registration number, the Remote ID serial number, and the remote pilot certificate number; repeat the registration at the end.", "The airport elevation, the length of the runway in use, and the current altimeter setting; repeat the altimeter setting at the end.", "The controller's name, the assigned transponder code, and the clearance being requested; repeat the transponder code at the end."], "explanation": "Aircraft identification is essential; addressee, position, and intentions alone are incomplete.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "AIM § 4-1-9 — Self-announce position and intentions", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap4_section_1.html"}},
  {"id": 62, "category": "Airport & Radio", "difficulty": "Foundation", "question": "What do AWOS and ASOS provide?", "answer": "Automated surface weather observations.", "distractors": ["Air traffic control clearances.", "Collision-avoidance advisories for aircraft in the pattern.", "LAANC approvals, NOTAM updates, and Remote ID status."], "explanation": "They can report wind, visibility, ceiling, temperature, dew point, and altimeter data depending on the system.", "source": {"label": "FAA Pilot’s Handbook of Aeronautical Knowledge", "reference": "Aviation weather services", "url": "https://www.faa.gov/regulations_policies/handbooks_manuals/aviation/phak"}},
  {"id": 63, "category": "Airport & Radio", "difficulty": "Applied", "question": "What rotating-beacon colors identify a lighted civilian land airport?", "answer": "Alternating white and green.", "distractors": ["Alternating white and yellow.", "Alternating white and blue.", "Alternating green and yellow."], "explanation": "Beacon patterns help identify airport types at night or in reduced visibility.", "source": {"label": "FAA Pilot’s Handbook of Aeronautical Knowledge", "reference": "Airport lighting and beacons", "url": "https://www.faa.gov/regulations_policies/handbooks_manuals/aviation/phak"}},
  {"id": 64, "category": "Airport & Radio", "difficulty": "Scenario", "question": "Your site is outside controlled airspace but lies directly under an airport's traffic pattern. Is the operation acceptable on that basis?", "answer": "No. You must avoid interfering with airport operations and traffic patterns.", "distractors": ["Yes. Being outside controlled airspace is enough to make the operation acceptable.", "Yes. Staying below 400 feet AGL removes the need to avoid the traffic pattern.", "No. It is permitted only while you monitor the airport's CTAF throughout the flight."], "explanation": "Airspace authorization and safe airport-vicinity operation are separate requirements.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.43", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 65, "category": "Airport & Radio", "difficulty": "Foundation", "question": "Why must a remote pilot check NOTAMs before flight?", "answer": "They contain time-sensitive aeronautical information that may affect the operation, including closures, hazards, and flight restrictions.", "distractors": ["They restate aeronautical information that is already printed on the current sectional chart, so a pilot holding a current chart has the same details.", "They contain long-range weather forecasts for the region but say nothing about closures, hazards, or airspace restrictions.", "They list the ceiling altitudes available through LAANC for each airspace grid surrounding a controlled airport."], "explanation": "A chart can be current yet still omit short-notice conditions announced by NOTAM.", "source": {"label": "FAA-S-ACS-10B", "reference": "Area II — Sources for flight restrictions", "url": "https://www.faa.gov/sites/faa.gov/files/training_testing/testing/acs/uas_acs.pdf"}},
  {"id": 66, "category": "Airport & Radio", "difficulty": "Scenario", "question": "A helicopter appears on short final toward a nearby pad while your drone is airborne. What should you do?", "answer": "Yield immediately, keep the drone well clear, and land or reposition safely as needed.", "distractors": ["Hold the drone in place because the helicopter must yield to traffic already airborne.", "Climb the drone above the traffic pattern so the helicopter can pass underneath.", "Continue the mission below 400 feet AGL after announcing the drone's position on CTAF."], "explanation": "The small UAS must yield to all aircraft, and the remote PIC may not interfere with heliport traffic patterns.", "source": {"label": "14 CFR Part 107", "reference": "§§ 107.37 and 107.43", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 67, "category": "Performance & Loading", "difficulty": "Foundation", "question": "What is center of gravity (CG)?", "answer": "The point at which the aircraft would balance if suspended.", "distractors": ["The geometric center of the aircraft, regardless of payload weight.", "The location of the aircraft's heaviest individual component.", "The point where the total lift force acts on the airframe."], "explanation": "Payload placement can move the CG and change stability, control authority, and power required.", "source": {"label": "FAA Pilot’s Handbook of Aeronautical Knowledge", "reference": "Weight and balance", "url": "https://www.faa.gov/regulations_policies/handbooks_manuals/aviation/phak"}},
  {"id": 68, "category": "Performance & Loading", "difficulty": "Applied", "question": "How does high density altitude generally affect a small UAS?", "answer": "It reduces aerodynamic and propeller performance, often requiring more power for the same result.", "distractors": ["It increases propeller efficiency and reduces the power required to hold a steady hover.", "It changes the battery discharge rate but leaves propeller thrust and climb rate unchanged.", "It increases air density, improving climb rate and noticeably extending endurance."], "explanation": "Hot, high, humid, or low-pressure conditions can reduce lift, thrust, climb performance, and endurance.", "source": {"label": "FAA Pilot’s Handbook of Aeronautical Knowledge", "reference": "Aircraft performance", "url": "https://www.faa.gov/regulations_policies/handbooks_manuals/aviation/phak"}},
  {"id": 69, "category": "Performance & Loading", "difficulty": "Foundation", "question": "What is the usual effect of adding weight to a small UAS?", "answer": "Higher power demand, reduced climb performance and endurance, and greater kinetic energy.", "distractors": ["Lower power demand, with a normal increase in available flight endurance.", "Improved climb performance, with no change in the aircraft's kinetic energy.", "A shifted center of gravity, but unchanged climb rate and endurance below 55 pounds."], "explanation": "The exact effect depends on the aircraft, but added mass never comes free; manufacturer limits still control.", "source": {"label": "FAA Remote Pilot Study Guide", "reference": "Chapter 4 — Loading", "url": "https://www.faa.gov/sites/faa.gov/files/regulations_policies/handbooks_manuals/aviation/remote_pilot_study_guide.pdf"}},
  {"id": 70, "category": "Performance & Loading", "difficulty": "Applied", "question": "What must the remote PIC verify about an attached payload before flight?", "answer": "It is secure and does not adversely affect flight characteristics or controllability.", "distractors": ["It is secure, and nothing more, since any effect on handling is the manufacturer's concern.", "It is secure; any effect on control can be left to the flight-control software to compensate.", "It can be released in flight, even when the mission calls for no release at all."], "explanation": "The complete aircraft must also remain within its applicable weight and operating limits.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.49(e)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 71, "category": "Performance & Loading", "difficulty": "Applied", "question": "Why is an out-of-limit aft CG hazardous?", "answer": "It can reduce stability and make recovery from a disturbance more difficult.", "distractors": ["It increases stability and makes recovery from a disturbance easier.", "It shortens battery endurance without affecting handling or stability.", "It makes the aircraft nose-heavy and guarantees greater pitch-control authority."], "explanation": "CG limits are aircraft-specific; flight-control software cannot be assumed to compensate for an unsafe loading condition.", "source": {"label": "FAA Pilot’s Handbook of Aeronautical Knowledge", "reference": "CG effects and stability", "url": "https://www.faa.gov/regulations_policies/handbooks_manuals/aviation/phak"}},
  {"id": 72, "category": "Performance & Loading", "difficulty": "Scenario", "question": "A camera is mounted far forward and the drone hovers with a persistent rearward tilt. What is the best response?", "answer": "Land and correct the loading or mounting before continuing.", "distractors": ["Continue the flight, since the controller's compensation proves the loading is acceptable.", "Increase groundspeed until aerodynamic forces level the aircraft.", "Recalibrate the compass while airborne to remove the rearward hover tilt."], "explanation": "A control system constantly compensating for poor balance wastes power and may have less authority left for wind or maneuvering.", "source": {"label": "FAA Remote Pilot Study Guide", "reference": "Chapter 4 — Loading and performance", "url": "https://www.faa.gov/sites/faa.gov/files/regulations_policies/handbooks_manuals/aviation/remote_pilot_study_guide.pdf"}},
  {"id": 73, "category": "Performance & Loading", "difficulty": "Foundation", "question": "What happens to load factor as a level turn becomes steeper?", "answer": "Load factor increases.", "distractors": ["Load factor decreases.", "Load factor stays at one.", "Load factor drops to zero."], "explanation": "More total lift is required to support weight while also turning, which increases structural and performance demand.", "source": {"label": "FAA Pilot’s Handbook of Aeronautical Knowledge", "reference": "Aerodynamics of flight — load factor", "url": "https://www.faa.gov/regulations_policies/handbooks_manuals/aviation/phak"}},
  {"id": 74, "category": "Performance & Loading", "difficulty": "Applied", "question": "How can cold weather affect lithium-based flight batteries?", "answer": "It can reduce available capacity and voltage performance, shortening endurance and increasing sag under load.", "distractors": ["It increases available capacity and reduces voltage sag under load, extending endurance.", "It makes the charge indicator read low before takeoff, though the pack still delivers its full rated flight time.", "It changes charging time but does not affect in-flight endurance or power delivery."], "explanation": "Follow manufacturer temperature guidance and use a larger landing reserve when conditions warrant.", "source": {"label": "FAA Safety Briefing — Cold Batteries", "reference": "Cold-weather battery capacity, resistance, and endurance", "url": "https://www.faa.gov/sites/faa.gov/files/NovDec2023.pdf"}},
  {"id": 75, "category": "Performance & Loading", "difficulty": "Scenario", "question": "One propeller has a small chip, but the aircraft still arms normally. Should the flight continue?", "answer": "No—replace or service the propeller according to manufacturer guidance before flight.", "distractors": ["Continue the flight because normal arming confirms that the chipped propeller is airworthy.", "Remove an equal amount of material from the opposite propeller to restore balance, then fly normally.", "Fly the mission now and replace the propeller at the next scheduled maintenance interval."], "explanation": "Damage can create imbalance, vibration, loss of efficiency, or failure that may not appear during a brief idle check.", "source": {"label": "FAA AC 107-2A", "reference": "Maintenance and preflight inspection", "url": "https://www.faa.gov/regulations_policies/advisory_circulars/index.cfm/go/document.information/documentID/1038977"}},
  {"id": 76, "category": "Performance & Loading", "difficulty": "Scenario", "question": "You fly outbound with a strong tailwind. What hidden return-flight risk must you plan for?", "answer": "The return leg will face a headwind and may require much more time and battery energy.", "distractors": ["The return leg will also have a tailwind and will require less battery energy than the outbound leg.", "The wind effects cancel over a round trip, so outbound battery use alone is enough for planning.", "The return leg will lose GPS reception because the aircraft is turning into the wind."], "explanation": "Plan energy using the least favorable leg, maintain reserves, and turn back early enough to land safely.", "source": {"label": "FAA-S-ACS-10B", "reference": "Area III, Task B, UA.III.B.K1b — Wind and currents", "url": "https://www.faa.gov/sites/faa.gov/files/training_testing/testing/acs/uas_acs.pdf"}},
  {"id": 77, "category": "ADM & Human Factors", "difficulty": "Foundation", "question": "What is aeronautical decision-making (ADM)?", "answer": "A systematic approach to choosing the best action in response to a given set of circumstances.", "distractors": ["An immediate reflex response that avoids deliberate comparison of alternatives.", "The manufacturer-prescribed maintenance schedule that keeps an aircraft in a serviceable condition.", "The air traffic control process used to separate aircraft in controlled airspace."], "explanation": "Good ADM identifies hazards, assesses risk, and selects controls before the situation becomes an emergency.", "source": {"label": "FAA Pilot’s Handbook of Aeronautical Knowledge", "reference": "Chapter 2 — Aeronautical Decision-Making", "url": "https://www.faa.gov/regulations_policies/handbooks_manuals/aviation/phak"}},
  {"id": 78, "category": "ADM & Human Factors", "difficulty": "Foundation", "question": "What four risk areas make up the PAVE checklist?", "answer": "Pilot, Aircraft, enVironment, and External pressures.", "distractors": ["Planning, Airspace, Visibility, and Equipment.", "Pilotage, Airport, Vehicle, and Emergency equipment.", "Performance, Altitude, Velocity, and Endurance reserves."], "explanation": "PAVE helps organize a preflight risk assessment so one attractive mission goal does not hide a critical weakness.", "source": {"label": "FAA Pilot’s Handbook of Aeronautical Knowledge", "reference": "PAVE risk checklist", "url": "https://www.faa.gov/regulations_policies/handbooks_manuals/aviation/phak"}},
  {"id": 79, "category": "ADM & Human Factors", "difficulty": "Foundation", "question": "What does the IMSAFE checklist evaluate?", "answer": "Illness, Medication, Stress, Alcohol, Fatigue, and Emotion.", "distractors": ["Instruments, Maintenance, Systems, Airspace, Fuel, and Environment.", "Identity, Mission, Skill, Altitude, Fuel, and Engine.", "Inspection, Maneuvers, Security, Airspace, Frequency, and Endurance."], "explanation": "It is a personal-fitness screen, not a substitute for honestly deciding whether you can operate safely.", "source": {"label": "FAA Pilot’s Handbook of Aeronautical Knowledge", "reference": "IMSAFE checklist", "url": "https://www.faa.gov/regulations_policies/handbooks_manuals/aviation/phak"}},
  {"id": 80, "category": "ADM & Human Factors", "difficulty": "Applied", "question": "What are the three steps in the 3P risk-management model?", "answer": "Perceive hazards, Process their impact, and Perform risk controls.", "distractors": ["Plan the route, Pilot the aircraft, and Park safely.", "Predict the outcome, Prepare the aircraft, and Proceed with the mission.", "Preflight the aircraft, Program the mission, and Proceed to launch."], "explanation": "The loop repeats as conditions change throughout the mission.", "source": {"label": "FAA Pilot’s Handbook of Aeronautical Knowledge", "reference": "3P model", "url": "https://www.faa.gov/regulations_policies/handbooks_manuals/aviation/phak"}},
  {"id": 81, "category": "ADM & Human Factors", "difficulty": "Foundation", "question": "Which antidote counters the hazardous attitude “The rules do not apply to me”?", "answer": "“Follow the rules. They are usually right.”", "distractors": ["“Not so fast. Think first.”", "“Taking chances is foolish.”", "“I am not helpless. I can make a difference.”"], "explanation": "The underlying hazardous attitude is anti-authority.", "source": {"label": "FAA Remote Pilot Study Guide", "reference": "Chapter 10 — Hazardous attitudes", "url": "https://www.faa.gov/sites/faa.gov/files/regulations_policies/handbooks_manuals/aviation/remote_pilot_study_guide.pdf"}},
  {"id": 82, "category": "ADM & Human Factors", "difficulty": "Foundation", "question": "Which antidote counters impulsivity?", "answer": "“Not so fast. Think first.”", "distractors": ["“Follow the rules. They are usually right.”", "“It could happen to me.”", "“Taking chances is foolish.”"], "explanation": "A deliberate pause breaks the urge to act immediately without comparing safer options.", "source": {"label": "FAA Remote Pilot Study Guide", "reference": "Chapter 10 — Hazardous attitudes", "url": "https://www.faa.gov/sites/faa.gov/files/regulations_policies/handbooks_manuals/aviation/remote_pilot_study_guide.pdf"}},
  {"id": 83, "category": "ADM & Human Factors", "difficulty": "Foundation", "question": "Which antidote counters invulnerability?", "answer": "“It could happen to me.”", "distractors": ["“Not so fast. Think first.”", "“Follow the rules. They are usually right.”", "“Taking chances is foolish.”"], "explanation": "Recognizing personal exposure makes risk controls feel relevant rather than optional.", "source": {"label": "FAA Remote Pilot Study Guide", "reference": "Chapter 10 — Hazardous attitudes", "url": "https://www.faa.gov/sites/faa.gov/files/regulations_policies/handbooks_manuals/aviation/remote_pilot_study_guide.pdf"}},
  {"id": 84, "category": "ADM & Human Factors", "difficulty": "Foundation", "question": "Which antidote counters the macho attitude?", "answer": "“Taking chances is foolish.”", "distractors": ["“It could happen to me.”", "“Not so fast. Think first.”", "“I am not helpless. I can make a difference.”"], "explanation": "Skill is demonstrated by disciplined judgment, not by accepting needless risk.", "source": {"label": "FAA Remote Pilot Study Guide", "reference": "Chapter 10 — Hazardous attitudes", "url": "https://www.faa.gov/sites/faa.gov/files/regulations_policies/handbooks_manuals/aviation/remote_pilot_study_guide.pdf"}},
  {"id": 85, "category": "ADM & Human Factors", "difficulty": "Foundation", "question": "Which antidote counters resignation?", "answer": "“I am not helpless. I can make a difference.”", "distractors": ["“Not so fast. Think first.”", "“It could happen to me.”", "“Follow the rules. They are usually right.”"], "explanation": "The antidote redirects attention toward available actions, resources, and safer outcomes.", "source": {"label": "FAA Remote Pilot Study Guide", "reference": "Chapter 10 — Hazardous attitudes", "url": "https://www.faa.gov/sites/faa.gov/files/regulations_policies/handbooks_manuals/aviation/remote_pilot_study_guide.pdf"}},
  {"id": 86, "category": "ADM & Human Factors", "difficulty": "Scenario", "question": "A client pressures you to launch before a storm arrives because “it will only take five minutes.” Which risk factor is most obvious?", "answer": "External pressure.", "distractors": ["Aircraft risk from deferred maintenance.", "Pilot risk from illness or medication.", "Invulnerability."], "explanation": "A firm personal minimum and a preplanned cancellation trigger help prevent schedule or customer pressure from driving unsafe choices.", "source": {"label": "FAA Pilot’s Handbook of Aeronautical Knowledge", "reference": "PAVE — External pressures", "url": "https://www.faa.gov/regulations_policies/handbooks_manuals/aviation/phak"}},
  {"id": 87, "category": "ADM & Human Factors", "difficulty": "Applied", "question": "What alcohol limits apply to a remote PIC, control manipulator, or visual observer?", "answer": "No duty within 8 hours after drinking, while under the influence, with a blood alcohol level of 0.04% or greater, or while using an impairing drug.", "distractors": ["No duty within 12 hours after drinking, while under the influence, with a blood alcohol level of 0.08% or greater, or while using an impairing drug.", "No duty within 8 hours after drinking; after 8 hours, the person may serve regardless of continuing impairment or alcohol concentration.", "No duty within 24 hours after drinking or with a blood alcohol level of 0.02% or greater, but nonprescription drugs are unrestricted."], "explanation": "Legal minimums do not guarantee fitness; impairment can persist after the numeric limits are met.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.27 incorporating § 91.17", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 88, "category": "ADM & Human Factors", "difficulty": "Applied", "question": "What is the core purpose of crew resource management in a small UAS operation?", "answer": "Use people, information, and equipment effectively to manage risk and maintain shared situational awareness.", "distractors": ["Centralize every operational decision with the remote PIC and discourage crewmembers from challenging it.", "Maximize mission speed by shortening briefings and delegating risk decisions to automation.", "Replace standard procedures with informal communication whenever an experienced crew is working together."], "explanation": "Clear roles, challenge-and-response communication, and permission to call “stop” help catch errors early.", "source": {"label": "FAA-S-ACS-10B", "reference": "Area V — Crew resource management", "url": "https://www.faa.gov/sites/faa.gov/files/training_testing/testing/acs/uas_acs.pdf"}},
  {"id": 89, "category": "Operations & Safety", "difficulty": "Foundation", "question": "Before each flight, what must the remote PIC determine about the small UAS?", "answer": "That the small UAS is in a condition for safe operation.", "distractors": ["That the small UAS is still under warranty.", "That the small UAS has flown fewer than 100 hours since its last service.", "That the small UAS has passed an annual FAA airworthiness inspection."], "explanation": "The check should cover the complete system and mission configuration, not merely whether the aircraft powers on.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.15(a)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 90, "category": "Operations & Safety", "difficulty": "Applied", "question": "What must be verified about control links during the preflight assessment?", "answer": "That all links between the ground control station and aircraft are working properly.", "distractors": ["That the GPS signal is strong, since the aircraft checks the control link itself during startup.", "That the Remote ID broadcast is active, because it carries the control signal.", "That the anti-collision lights and camera downlink work, with the control link checked after takeoff."], "explanation": "The remote PIC should also understand lost-link behavior and site-specific interference risks.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.49(c)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 91, "category": "Operations & Safety", "difficulty": "Applied", "question": "How much battery is “enough” for a planned Part 107 flight?", "answer": "Enough for the intended operation plus a prudent reserve for foreseeable contingencies.", "distractors": ["Enough for the advertised maximum flight time, with no reserve held for wind or delay.", "Enough to reach the farthest mission point, since low-battery mode will bring the aircraft home.", "Exactly a 10 percent reserve, whatever the weather, battery condition, or landing alternatives."], "explanation": "The rule requires sufficient available power; good risk management adds margin for wind, delay, rerouting, and battery variation.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.49(d)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 92, "category": "Operations & Safety", "difficulty": "Scenario", "question": "Midflight vibration suggests the aircraft may no longer be safe. What must the remote PIC do?", "answer": "Discontinue the flight and land safely as soon as practical.", "distractors": ["Continue at reduced speed and inspect the aircraft after landing.", "Hover in place until the vibration can be diagnosed.", "Command an immediate high-speed return-to-home instead of landing nearby."], "explanation": "A person may not continue when they know or have reason to know the small UAS is no longer in a safe condition.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.15(b)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 93, "category": "Operations & Safety", "difficulty": "Scenario", "question": "Before launch, what should the crew know about a loss of command-and-control link?", "answer": "How the aircraft will respond, where it may travel, and when the crew will trigger the safest contingency action.", "distractors": ["How to enable return-to-home before takeoff, which by itself covers every lost-link situation.", "How much battery remains when the link drops, since the remaining flight time sets where the aircraft comes down.", "How ATC will track the aircraft and where the agency will recover it after the control link is lost."], "explanation": "Return-to-home settings, altitude, obstacles, geofencing, and recovery areas must be evaluated for the actual site.", "source": {"label": "FAA AC 107-2A", "reference": "Contingency planning and lost link", "url": "https://www.faa.gov/regulations_policies/advisory_circulars/index.cfm/go/document.information/documentID/1038977"}},
  {"id": 94, "category": "Operations & Safety", "difficulty": "Scenario", "question": "A drone begins an uncommanded flyaway toward occupied space. What is the remote PIC’s priority?", "answer": "Protect people and other aircraft, execute the planned emergency response, and notify appropriate authorities when needed.", "distractors": ["Preserve the aircraft by chasing it on foot and attempting to catch it before it reaches occupied space.", "Restore the video feed first, because command of the aircraft cannot be regained until the camera downlink returns.", "Complete the current image capture, then warn anyone standing in the aircraft’s projected path."], "explanation": "Do not fixate on saving the aircraft at the expense of airspace awareness or public safety.", "source": {"label": "FAA AC 107-2A", "reference": "Emergency procedures", "url": "https://www.faa.gov/regulations_policies/advisory_circulars/index.cfm/go/document.information/documentID/1038977"}},
  {"id": 95, "category": "Operations & Safety", "difficulty": "Scenario", "question": "A low-flying manned aircraft suddenly enters the operating area. What action takes priority?", "answer": "Yield immediately and maneuver or land the drone to remain well clear.", "distractors": ["Hold position and let the manned aircraft maneuver around the drone.", "Climb the drone above the manned aircraft so their flight paths no longer intersect.", "Continue the mission, since a drone below 400 feet AGL has the right of way."], "explanation": "The small UAS always bears the duty to yield; mission completion is secondary.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.37", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 96, "category": "Operations & Safety", "difficulty": "Applied", "question": "If a visual observer is used, what communication standard applies?", "answer": "The remote PIC, control manipulator, and visual observer must maintain effective communication at all times.", "distractors": ["Communication must be confirmed before launch and again every 30 minutes while the aircraft is airborne.", "The crew must use aviation radio continuously, even when another effective communication method is available.", "The visual observer may operate independently without communicating as long as the observer can still see the drone."], "explanation": "They must coordinate scanning and maintain awareness of the aircraft’s position.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.33", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 97, "category": "Operations & Safety", "difficulty": "Scenario", "question": "When may a Part 107 pilot operate a drone from a moving land or water vehicle without a waiver?", "answer": "Only over a sparsely populated area and not while transporting another person’s property for compensation or hire.", "distractors": ["Over any area at all, provided the vehicle stays below 25 miles per hour and the drone stays below 400 feet AGL.", "Over a densely populated area, provided everyone inside the vehicle has consented to the operation.", "From a moving land vehicle, a watercraft, or an aircraft in flight, provided the operation is not for compensation or hire."], "explanation": "Operation from a moving aircraft is prohibited under the standard rule.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.25", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 98, "category": "Operations & Safety", "difficulty": "Applied", "question": "What makes a small UAS eligible for Category 1 operations over people?", "answer": "It weighs 0.55 pounds or less throughout the operation, including attachments, and has no exposed rotating parts that would lacerate human skin.", "distractors": ["It weighs less than 55 pounds and uses propeller guards, regardless of the injury those rotating parts could still cause on contact.", "It weighs 0.55 pounds or less at takeoff and carries an FAA-accepted declaration of compliance for that aircraft model.", "It weighs 3 pounds or less, broadcasts Remote ID, and is flown no faster than 10 knots whenever it passes over people."], "explanation": "Sustained flight over an open-air assembly also requires applicable Remote ID compliance.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.110", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 99, "category": "Operations & Safety", "difficulty": "Applied", "question": "What major restriction distinguishes Category 3 operations over people?", "answer": "They may not be conducted over open-air assemblies and are limited to specified controlled-site or non-sustained-flight conditions.", "distractors": ["They may be conducted over an open-air assembly of people whenever the drone broadcasts Remote ID for the whole flight.", "They may include unrestricted sustained flight over moving vehicles, but not any flight at all over stationary people.", "They are limited to drones weighing 0.55 pounds or less and therefore carry no site-access restrictions at all."], "explanation": "At a closed or restricted-access site, people must be on notice; otherwise sustained flight is limited to participants or protected people.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.125", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 100, "category": "Operations & Safety", "difficulty": "Scenario", "question": "A Category 2 drone must cross a public road with moving traffic. What standard Part 107 limitation applies?", "answer": "It must not maintain sustained flight over moving vehicles unless the operation is within or over a closed/restricted-access site where vehicle occupants are on notice.", "distractors": ["It may maintain sustained flight over moving vehicles as long as the drone remains below 400 feet AGL above the roadway.", "It may maintain sustained flight over moving vehicles because that limitation applies only to drones heavier than 0.55 pounds.", "It must not fly over moving vehicles at any time, even within or over a closed or restricted-access site where the vehicle occupants have been put on notice."], "explanation": "The aircraft must also meet its Category 2 operating requirements; a brief transit is not permission to loiter over traffic.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.145", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 101, "category": "Regulations", "difficulty": "Foundation", "question": "Under Part 107, what is a control station?", "answer": "The interface a remote pilot uses to control the flight path of the small unmanned aircraft.", "distractors": ["The physical takeoff and landing area reserved for the small unmanned aircraft.", "The Remote ID module that broadcasts the aircraft's identification and location.", "The radio-frequency data link that carries commands between the operator and the aircraft."], "explanation": "A control station is defined by its function; it can be a handheld controller, computer interface, or another system used to direct the aircraft.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.3 — Control station", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 102, "category": "Regulations", "difficulty": "Foundation", "question": "What does the term “small unmanned aircraft system” include beyond the aircraft itself?", "answer": "The associated elements required for safe and efficient operation, including communication links and control components.", "distractors": ["The payload it carries, but not the control station or the data link used to fly it.", "The remote PIC, the person manipulating the controls, and the visual observer, who are components of the system.", "Its airspace authorization and the operator's liability insurance."], "explanation": "Part 107 distinguishes the aircraft from the complete system used to operate it in the National Airspace System.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.3 — Small unmanned aircraft system", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 103, "category": "Regulations", "difficulty": "Applied", "question": "What documents must a remote PIC physically possess and keep readily accessible while exercising certificate privileges?", "answer": "A Remote Pilot Certificate with a small UAS rating and identification.", "distractors": ["The Remote Pilot Certificate on its own; separate identification is not required.", "The aircraft registration certificate and government identification, but not the pilot certificate.", "A medical certificate and a flight logbook."], "explanation": "Having a certificate number saved elsewhere is not enough; the certificate and acceptable identification must be physically possessed and readily accessible.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.7(a)(1)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 104, "category": "Regulations", "difficulty": "Foundation", "question": "Who may request to inspect a remote pilot’s certificate and identification under § 107.7?", "answer": "The FAA Administrator, an authorized NTSB or TSA representative, or any federal, state, or local law-enforcement officer.", "distractors": ["The remote pilot's employer or client, or the owner of the property over which the flight was conducted.", "The FAA Administrator, an authorized NTSB representative, or the manager of the airport nearest the operation.", "An authorized TSA representative or a federal law-enforcement officer; state and local officers must route the request through the FAA."], "explanation": "The regulation expressly identifies these officials; a certificated remote pilot must present the documents when one of them requests inspection.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.7(a)(2)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 105, "category": "Regulations", "difficulty": "Scenario", "question": "The FAA Administrator requests a compliance inspection during an inquiry. What must the Part 107 participants allow?", "answer": "They must allow the Administrator to test or inspect the small UAS, the remote PIC, the person manipulating the flight controls, and—if used—the visual observer.", "distractors": ["Participants must allow an inspection after the flight has ended, because the FAA may not request one while an operation is under way.", "Participants must provide maintenance records, but the FAA may not inspect the aircraft or the applicable crewmembers.", "Participants may postpone every requested test or inspection for 30 calendar days without FAA approval."], "explanation": "The remote PIC, visual observer, owner, operator, or control manipulator may have to allow access, but the owner and operator are not listed as inspection subjects.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.7(b)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 106, "category": "Regulations", "difficulty": "Scenario", "question": "A visual observer knows a medication is slowing their reactions. May that person participate in the operation?", "answer": "No, not if the condition could interfere with safe operation.", "distractors": ["Yes, because the medication rule applies to the remote PIC but not to a visual observer.", "Yes, if the visual observer is supervised by a remote PIC who has not taken the medication.", "Yes, because a prescribed or over-the-counter medication is permitted regardless of its effect on reaction time."], "explanation": "The medical-condition rule applies to the remote PIC, control manipulator, visual observer, and any direct participant—not only to the person holding the controller.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.17", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 107, "category": "Regulations", "difficulty": "Applied", "question": "What must the remote PIC ensure would be true if control of the drone were lost for any reason?", "answer": "The drone would pose no undue hazard to other people, other aircraft, or other property.", "distractors": ["The drone would descend below 400 feet AGL and hold that altitude until the control link is restored.", "The drone's automatic return-to-home function would recover it to the launch point.", "The drone could be recovered without damage, even if its flight path created a hazard to others."], "explanation": "Site selection, containment areas, lost-link settings, and safe routing should all support this required outcome.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.19(c)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 108, "category": "Regulations", "difficulty": "Foundation", "question": "What kind of operation does Part 107 prohibit as careless or reckless?", "answer": "An operation conducted in a manner that endangers another person’s life or property.", "distractors": ["An operation that damages the small unmanned aircraft itself but harms no other person or property.", "A flight flown without liability insurance, even when no one is endangered.", "A flight that loses GPS reception in the air while the remote PIC keeps full control."], "explanation": "Meeting numerical limits does not excuse conduct that creates an unreasonable danger.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.23(a)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 109, "category": "Regulations", "difficulty": "Scenario", "question": "May a remote pilot control a Part 107 drone while riding in a moving aircraft?", "answer": "No. Part 107 prohibits operating a small UAS from a moving aircraft.", "distractors": ["Yes, when the moving aircraft is over a sparsely populated area and the drone carries no property for compensation.", "Yes, when the remote pilot remains below 400 feet AGL and maintains visual line of sight.", "Yes, when another certificated remote pilot is aboard the moving aircraft and can take control."], "explanation": "Part 107 prohibits operating a small UAS from a moving aircraft; the limited exception applies only to certain operations from moving land or water-borne vehicles.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.25(a)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 110, "category": "Regulations", "difficulty": "Foundation", "question": "May a small UAS carry hazardous material during a standard Part 107 operation?", "answer": "No. A small unmanned aircraft may not carry hazardous material.", "distractors": ["Yes, if the entire drone and hazardous payload weigh 0.55 pounds or less.", "Yes, if the material is packaged and secured according to the manufacturer’s instructions.", "Yes, whenever the remote PIC documents the material during the preflight assessment."], "explanation": "Section 107.36 prohibits a small unmanned aircraft from carrying material defined as hazardous under 49 CFR 171.8.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.36", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 111, "category": "Regulations", "difficulty": "Applied", "question": "Outside Alaska, which periods count as civil twilight for the Part 107 lighting rule?", "answer": "The 30 minutes before official sunrise and the 30 minutes after official sunset.", "distractors": ["The 60 minutes before official sunrise and the 60 minutes after official sunset.", "The 30 minutes after official sunrise and the 30 minutes before official sunset.", "The entire period between official sunrise and official sunset."], "explanation": "Alaska uses the civil-twilight period defined in the Air Almanac rather than the standard 30-minute rule.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.29(b)–(c)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 112, "category": "Regulations", "difficulty": "Applied", "question": "Under the visual line of sight rule, what must the crew be able to determine by seeing the drone throughout the flight?", "answer": "Its location, attitude, altitude, and direction; surrounding air traffic or hazards; and whether it endangers another person or property.", "distractors": ["Its GPS coordinates, its remaining battery state, and whether its Remote ID broadcast is active.", "Its color and shape, and its orientation relative to the control station.", "Its exact groundspeed and its distance from the control station, calculated using unaided vision."], "explanation": "Merely seeing a distant dot is insufficient if the crew cannot make the determinations required by § 107.31.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.31(a)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 113, "category": "Regulations", "difficulty": "Applied", "question": "When a visual observer is used, what two observation tasks must the crew coordinate?", "answer": "Scanning the operating airspace for collision hazards and maintaining awareness of the drone’s position through direct visual observation.", "distractors": ["Monitoring the local weather at the launch site and recording each battery's charge cycles.", "Checking Remote ID broadcasts and reading GPS coordinates at the control station.", "Making radio calls to air traffic control and keeping the client informed of progress."], "explanation": "The remote PIC, control manipulator, and visual observer share these coordinated see-and-avoid duties.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.33(c)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 114, "category": "Regulations", "difficulty": "Foundation", "question": "Which four subjects must the remote PIC include in the required preflight assessment of the operating environment?", "answer": "Local weather, local airspace and flight restrictions, the location of people and property on the surface, and other ground hazards.", "distractors": ["Battery charge state, propeller condition, firmware version, and camera exposure settings.", "Aircraft registration, liability insurance, written client permission, and local privacy rules.", "Pilot fitness, payload value, expected mission revenue, and postflight data storage."], "explanation": "The assessment must consider risks both on the surface and in the air in the immediate vicinity.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.49(a)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 115, "category": "Regulations", "difficulty": "Applied", "question": "What information must the remote PIC give everyone directly participating in the operation before flight?", "answer": "The operating conditions, emergency and contingency procedures, roles and responsibilities, and potential hazards.", "distractors": ["The planned route, the maximum altitude, and the estimated duration of the flight.", "Copies of the remote pilot certificate, the aircraft registration, and the airspace authorization.", "The client's desired images, the project deadline, the payment terms, and the delivery method."], "explanation": "A complete crew briefing creates shared expectations before anyone performs an operational role.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.49(b)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 116, "category": "Regulations", "difficulty": "Scenario", "question": "A current flight restriction conflicts with a planned Part 107 mission. May the remote PIC ignore it because the drone will remain below 400 feet?", "answer": "No. The remote PIC must comply with the applicable flight restriction.", "distractors": ["Yes, because flight restrictions apply to manned aircraft but not to drones below 400 feet AGL.", "Yes, if the remote PIC remains in Class G airspace and maintains visual line of sight.", "Yes, if the mission lasts less than 30 minutes and no manned aircraft are visible."], "explanation": "Section 107.47 requires the remote PIC to comply with the applicable flight restrictions in §§ 91.137 through 91.145 and § 99.7.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.47", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 117, "category": "Regulations", "difficulty": "Foundation", "question": "May a Part 107 small UAS operate with an ATC transponder switched on?", "answer": "Only if the FAA Administrator has authorized it; otherwise the transponder must not be on.", "distractors": ["The transponder must be switched on whenever the drone enters controlled airspace.", "The transponder may be switched on whenever it was installed by the aircraft manufacturer.", "The transponder is required for every Part 107 flight above 200 feet AGL."], "explanation": "Part 107 separately restricts transponder transmission to prevent unnecessary surveillance-system effects.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.52", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 118, "category": "Regulations", "difficulty": "Foundation", "question": "May a Part 107 small UAS transmit ADS-B Out during flight?", "answer": "Only if the FAA Administrator has authorized it; otherwise ADS-B Out may not be in transmit mode.", "distractors": ["ADS-B Out must transmit during every operation in Class B, C, or D airspace.", "ADS-B Out may transmit at the remote PIC's discretion during any Part 107 operation.", "ADS-B Out may transmit without authorization when the small UAS remains below 400 feet AGL."], "explanation": "Receiving traffic information is different from transmitting ADS-B Out; § 107.53 addresses the transmit function.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.53", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 119, "category": "Regulations", "difficulty": "Foundation", "question": "For how long may the FAA issue a temporary Remote Pilot Certificate with a small UAS rating?", "answer": "Up to 120 calendar days.", "distractors": ["Up to 60 calendar days.", "Up to 90 calendar days.", "Up to 24 calendar months, the same interval used for a flight review."], "explanation": "It can expire sooner on its printed expiration date, when the permanent certificate arrives, or when the applicant receives a denial or revocation notice.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.64", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 120, "category": "Regulations", "difficulty": "Foundation", "question": "How long must an applicant wait to retake an FAA knowledge test after failing it?", "answer": "14 calendar days.", "distractors": ["7 calendar days.", "14 business days, counted without weekends or holidays.", "30 calendar days."], "explanation": "The waiting period begins after the failed test and applies before the applicant may reapply.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.71", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 121, "category": "Regulations", "difficulty": "Applied", "question": "What is the application-and-testing consequence if the FAA finds that an applicant cheated on a knowledge test?", "answer": "For one year after the violation, the applicant may not apply for any certificate, rating, or authorization issued under 14 CFR Chapter I and may not apply for or take any test under that chapter.", "distractors": ["The applicant may not retake that knowledge test for 90 days, but may apply for other certificates immediately.", "The applicant may not apply for a certificate or take an FAA test for six calendar months.", "For two years after the violation, the applicant may not apply for any certificate or rating and may not take any FAA test."], "explanation": "A certificate or rating the person already holds may also be suspended or revoked.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.69", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 122, "category": "Regulations", "difficulty": "Scenario", "question": "A remote pilot changed permanent mailing addresses 31 days ago but has not notified the FAA. May the pilot exercise certificate privileges?", "answer": "No, not until the FAA is notified of the address change.", "distractors": ["Yes, because certificate privileges continue for 60 days after a permanent address change.", "Yes, because the pilot may wait until the next certificate renewal to report the new address.", "Yes, because the 30-day reporting requirement covers a change of email address rather than a change of permanent mailing address."], "explanation": "Section 107.77 gives a certificate holder 30 days after a permanent mailing-address change before privileges become unavailable.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.77(c)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 123, "category": "Regulations", "difficulty": "Applied", "question": "What injury-severity limit must a drone meet to be eligible for Category 2 operations over people?", "answer": "It must not cause injury equivalent to or greater than an 11-foot-pound rigid-object impact.", "distractors": ["The drone must not cause injury equivalent to or greater than a 25-foot-pound rigid-object impact.", "The drone must weigh 0.55 pounds or less throughout the operation, regardless of impact severity.", "Its impact must transfer no more than 11 joules of kinetic energy to the person it strikes."], "explanation": "The design must also have no exposed rotating parts that would lacerate skin and no safety defects, and the aircraft must satisfy the applicable declaration and labeling rules.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.120(a)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 124, "category": "Regulations", "difficulty": "Applied", "question": "What injury-severity limit must a drone meet to be eligible for Category 3 operations over people?", "answer": "It must not cause injury equivalent to or greater than a 25-foot-pound rigid-object impact.", "distractors": ["The drone must not cause injury equivalent to or greater than an 11-foot-pound rigid-object impact.", "Its impact energy must stay at or below 55 foot-pounds, measured on a rigid-object strike.", "Its impact must transfer no more than 25 joules of kinetic energy to the person it strikes."], "explanation": "Category 3 also requires no exposed skin-lacerating rotating parts, no safety defects, and compliance with its declaration, labeling, and operating restrictions.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.130(a)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 125, "category": "Regulations", "difficulty": "Applied", "question": "What aircraft-level requirements distinguish a Category 4 operation over people?", "answer": "The drone must have a Part 21 airworthiness certificate, be operated within approved limitations that permit flight over people, and meet the prescribed maintenance and inspection requirements.", "distractors": ["The drone must weigh 0.55 pounds or less and have no exposed rotating parts capable of lacerating skin.", "The drone must meet the 11-foot-pound injury limit and have an FAA-accepted declaration of compliance, but needs no airworthiness certificate.", "The drone must meet the 25-foot-pound injury limit and remain over a closed site, but needs no approved operating limitations or maintenance program."], "explanation": "Category 4 relies on airworthiness certification and continued-airworthiness controls rather than the Category 1 weight limit or Category 2 and 3 injury thresholds.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.140", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 126, "category": "Airspace & Charts", "difficulty": "Scenario", "question": "A UAS Facility Map shows “200” over the planned site. Does that number itself authorize flight up to 200 feet AGL?", "answer": "No; the pilot must still obtain a Part 107 airspace authorization.", "distractors": ["Yes; the grid value is an automatic authorization during daylight hours.", "No; the pilot must first notify the nearest airport operator.", "Yes; a Standard Remote ID drone may use the published grid altitude."], "explanation": "The grid value is the maximum altitude the FAA may authorize without additional safety analysis, not permission to fly.", "source": {"label": "FAA UAS Facility Maps", "reference": "Maximum altitudes and authorization notice", "url": "https://www.faa.gov/uas/commercial_operators/uas_facility_maps"}},
  {"id": 127, "category": "Airspace & Charts", "difficulty": "Applied", "question": "How can a Part 107 pilot request an altitude above a UAS Facility Map value, including inside a zero-foot grid?", "answer": "Submit a LAANC further-coordination request for an altitude at or below 400 feet AGL at least 72 hours before the requested start time.", "distractors": ["Submit a standard LAANC request at the published grid altitude and climb above it after receiving the automatic approval.", "Submit a FAADroneZone waiver request at least 24 hours before launch for an altitude anywhere up to 1,200 feet AGL.", "Call the control tower immediately before launch and request a verbal altitude increase above the published grid value."], "explanation": "An Air Traffic Manager reviews the request; submitting it does not guarantee approval.", "source": {"label": "FAA Part 107 Airspace Authorizations", "reference": "LAANC further coordination", "url": "https://www.faa.gov/uas/commercial_operators/part_107_airspace_authorizations"}},
  {"id": 128, "category": "Airspace & Charts", "difficulty": "Applied", "question": "Which FAA system handles Part 107 authorization requests for airports that are not LAANC-enabled?", "answer": "FAADroneZone.", "distractors": ["The LAANC service desk.", "IACRA.", "The B4UFLY service."], "explanation": "Those requests are processed manually rather than through LAANC’s near-real-time approval path.", "source": {"label": "FAA Part 107 Airspace Authorizations", "reference": "FAADroneZone authorizations", "url": "https://www.faa.gov/uas/commercial_operators/part_107_airspace_authorizations"}},
  {"id": 129, "category": "Airspace & Charts", "difficulty": "Foundation", "question": "What are the general vertical limits of Class A airspace, and is it specifically charted on sectionals?", "answer": "It generally extends from 18,000 feet MSL through Flight Level 600 and is not specifically charted.", "distractors": ["It generally extends from 10,000 feet MSL through Flight Level 180 and is outlined by solid blue lines.", "It generally extends from 14,500 feet MSL through Flight Level 600 and is shown by shaded blue boundaries.", "It generally extends from the surface to but not including 18,000 feet MSL and is shown by dashed blue lines."], "explanation": "Class A is far above normal Part 107 altitudes, but its limits remain part of the FAA airspace-knowledge framework.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "AIM 3-2-2 — Class A Airspace", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap3_section_2.html"}},
  {"id": 130, "category": "Airspace & Charts", "difficulty": "Foundation", "question": "What are the usual dimensions of Class C airspace?", "answer": "A 5-NM-radius core from the surface to 4,000 feet above airport elevation and a 10-NM-radius shelf from no lower than 1,200 feet to 4,000 feet above airport elevation.", "distractors": ["A 4-NM-radius core from the surface to 2,500 feet above airport elevation, with no outer shelf, so the same radius applies from the surface to the top of the area.", "A 10-NM-radius core from the surface to 10,000 feet MSL and a 20-NM-radius shelf that begins at 1,200 feet AGL and extends to 10,000 feet MSL above the primary airport.", "A 5-NM-radius core from 700 feet AGL to 4,000 feet MSL and an outer shelf extending to 30 NM from the primary airport at those same vertical limits."], "explanation": "Every Class C area is individually tailored, so the current charted boundaries and altitudes control.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "AIM 3-2-4 — Class C Airspace", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap3_section_2.html"}},
  {"id": 131, "category": "Airspace & Charts", "difficulty": "Foundation", "question": "How high does Class D airspace generally extend above its primary airport?", "answer": "From the surface to 2,500 feet above airport elevation, with the top charted in MSL.", "distractors": ["From the surface to 400 feet AGL, with the top charted in AGL rather than MSL.", "From the surface to 4,000 feet above airport elevation, with the top charted in AGL.", "From 1,200 feet AGL up to but not including 18,000 feet MSL over the primary airport."], "explanation": "Class D dimensions are individually tailored, so the sectional and Chart Supplement must be used for the actual location.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "AIM 3-2-5 — Class D Airspace", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap3_section_2.html"}},
  {"id": 132, "category": "Airspace & Charts", "difficulty": "Scenario", "question": "What can happen to part-time Class D surface airspace when its control tower closes?", "answer": "It can revert to a Class E surface area or to Class G airspace, as published for that airport.", "distractors": ["It remains Class D continuously, even during the hours when the tower is closed.", "It automatically becomes Class G whenever the tower closes, regardless of what is published for that airport.", "It automatically converts to Class C airspace until the tower reopens for the day."], "explanation": "Check the Chart Supplement’s airspace entry and current NOTAMs rather than assuming the dashed-blue area remains Class D around the clock.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "AIM 3-2-5 — Part-time Class D status", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap3_section_2.html"}},
  {"id": 133, "category": "Airspace & Charts", "difficulty": "Applied", "question": "Do Class E transition areas beginning at 700 or 1,200 feet AGL turn off when a nearby airport tower closes?", "answer": "No; those transition areas remain in effect continuously.", "distractors": ["Yes; every 700- or 1,200-foot transition area turns off with the tower.", "Yes; it becomes Class G from the surface to 18,000 feet MSL.", "No; they lower to become a Class E surface area while the tower is closed."], "explanation": "Airport surface-area status can change with tower hours, but the charted 700-foot and 1,200-foot transition areas do not.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "AIM 3-2-6 — Class E transition areas", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap3_section_2.html"}},
  {"id": 134, "category": "Airspace & Charts", "difficulty": "Foundation", "question": "What class of airspace normally forms a federal airway, and what are its usual vertical limits?", "answer": "Class E airspace, normally from 1,200 feet AGL up to but not including 18,000 feet MSL.", "distractors": ["Class D airspace, normally from the surface to 2,500 feet above airport elevation.", "Class G airspace, normally from the surface up to but not including 700 feet AGL.", "Class A airspace, normally from 18,000 feet MSL through Flight Level 600."], "explanation": "A specifically designated segment may use a different floor, so the applicable chart remains controlling.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "AIM 3-2-6 — Federal airways and low-altitude RNAV routes", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap3_section_2.html"}},
  {"id": 135, "category": "Airspace & Charts", "difficulty": "Foundation", "question": "Which prefixes identify VOR federal airways and low-altitude RNAV routes?", "answer": "“V” identifies VOR federal airways; “T” identifies low-altitude RNAV T-routes; and “TK” identifies helicopter RNAV routes.", "distractors": ["“J” identifies VOR federal airways; “Q” identifies low-altitude RNAV routes; and “H” identifies helicopter RNAV routes.", "“L” identifies VOR federal airways; “R” identifies low-altitude RNAV routes; and “RK” identifies helicopter RNAV routes.", "“A” identifies VOR federal airways; “B” identifies low-altitude RNAV routes; and “BK” identifies helicopter RNAV routes."], "explanation": "The AIM states that low-altitude RNAV routes include both T-routes and TK helicopter RNAV routes.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "AIM 3-2-6 — Federal airway and RNAV route identifiers", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap3_section_2.html"}},
  {"id": 136, "category": "Airspace & Charts", "difficulty": "Foundation", "question": "Which two types of special-use airspace are regulatory?", "answer": "Prohibited areas and restricted areas.", "distractors": ["Alert areas and warning areas.", "Military operations areas and controlled firing areas.", "National security areas and alert areas."], "explanation": "Warning areas, military operations areas, alert areas, controlled firing areas, and national security areas are categorized as nonregulatory special-use airspace.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "AIM 3-4-1 — Special Use Airspace", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap3_section_4.html"}},
  {"id": 137, "category": "Airspace & Charts", "difficulty": "Foundation", "question": "What does a warning area tell a pilot?", "answer": "Potentially hazardous activity exists in defined airspace extending from 3 NM outward from the U.S. coast.", "distractors": ["Flight is prohibited over a sensitive land facility inside the United States.", "A high volume of pilot training occurs in defined airspace over inland domestic areas of the United States.", "Voluntary avoidance is requested in airspace established solely for national security."], "explanation": "A warning area can lie over domestic waters, international waters, or both and warns nonparticipating pilots of the danger.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "AIM 3-4-4 — Warning Areas", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap3_section_4.html"}},
  {"id": 138, "category": "Airspace & Charts", "difficulty": "Applied", "question": "What activity should a pilot expect in an alert area, and who is responsible for collision avoidance?", "answer": "A high volume of pilot training or unusual aerial activity; both participating and transiting pilots share collision-avoidance responsibility.", "distractors": ["Invisible hazards that require advance permission to enter; the controlling agency alone provides collision avoidance.", "Military exercises reserved for participating aircraft; those military pilots alone are responsible for collision avoidance.", "Concentrated pilot training or other unusual aerial activity; collision avoidance rests with the participating aircraft rather than with transiting pilots."], "explanation": "An alert area is advisory rather than a blanket prohibition, but it signals a need for heightened traffic awareness.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "AIM 3-4-6 — Alert Areas", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap3_section_4.html"}},
  {"id": 139, "category": "Airspace & Charts", "difficulty": "Applied", "question": "Why are controlled firing areas normally not shown on aeronautical charts?", "answer": "Their hazardous activity stops immediately when monitoring indicates a nonparticipating aircraft is approaching.", "distractors": ["Their locations and the activities conducted inside them are classified and cannot be published.", "Their boundaries are depicted only on IFR en route charts rather than on VFR sectional charts.", "Their hazardous activity is confined to altitudes below 500 feet AGL, too low to affect charted air traffic."], "explanation": "Because the activity is suspended, a nonparticipating aircraft should not have to alter its flight path around a controlled firing area.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "AIM 3-4-7 — Controlled Firing Areas", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap3_section_4.html"}},
  {"id": 140, "category": "Airspace & Charts", "difficulty": "Applied", "question": "What does a national security area ask pilots to do, and how can that request become mandatory?", "answer": "Pilots are asked to avoid it voluntarily; flight can be temporarily prohibited under § 99.7 and announced by NOTAM.", "distractors": ["Flight is always prohibited there, from the surface to 18,000 feet MSL, as regulatory special-use airspace.", "Pilots must obtain approval from the controlling agency before transiting; ATC issues that approval on request.", "Avoidance is requested rather than required; a prohibition is imposed under § 91.137 and takes effect with the next sectional edition."], "explanation": "An NSA protects locations requiring increased security and safety for facilities on the ground.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "AIM 3-4-8 — National Security Areas", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap3_section_4.html"}},
  {"id": 141, "category": "Airspace & Charts", "difficulty": "Foundation", "question": "All permanent special-use airspace except controlled firing areas is charted. What operating information does the chart show for it?", "answer": "Its hours of operation, altitude limits, and controlling agency.", "distractors": ["The forecast weather, radio frequency, and recommended cruising altitude.", "Its lateral boundary, the using agency’s phone number, and its establishment date.", "Its local-time hours, traffic-pattern altitude, and nearest flight service station."], "explanation": "These details help a pilot determine when the airspace may be active and whom to contact for status information.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "AIM 3-4-1 — Permanent SUA charting", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap3_section_4.html"}},
  {"id": 142, "category": "Airspace & Charts", "difficulty": "Scenario", "question": "A sectional shows no special-use area over the site. Could a temporary MOA or temporary restricted area still be active there?", "answer": "Yes; temporary MOAs and temporary restricted areas are not charted.", "distractors": ["Yes; only if the temporary area already appears on the current sectional.", "No; temporary special-use airspace exists only above 18,000 feet MSL.", "No; an uncharted area is not effective until the next 56-day chart cycle."], "explanation": "Check current NOTAM and FAA special-use-airspace information for temporary activity that a sectional cannot display.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "AIM 3-4-1 and 3-4-3 — Temporary SUA", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap3_section_4.html"}},
  {"id": 143, "category": "Airspace & Charts", "difficulty": "Applied", "question": "How can a pilot obtain the current status of a special-use airspace area?", "answer": "Contact the using or controlling agency and check applicable airspace NOTAMs and FAA SUA information.", "distractors": ["Check the sectional’s publication date, because a chart still inside its 56-day cycle shows which areas are active.", "Monitor the nearest airport’s CTAF, because every active special-use area broadcasts its status on that frequency.", "Assume the area is inactive unless an ATC controller contacts the pilot about it during the flight."], "explanation": "The chart-margin frequency can identify the controlling agency, while current notices reveal activations or temporary changes.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "AIM 3-4-9 — Obtaining SUA status", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap3_section_4.html"}},
  {"id": 144, "category": "Airspace & Charts", "difficulty": "Foundation", "question": "What is the scale of an FAA Sectional Aeronautical Chart?", "answer": "1:500,000, or about 6.86 nautical miles per inch.", "distractors": ["1:250,000, or about 3.43 nautical miles per inch.", "1:1,000,000, or about 13.7 nautical miles per inch.", "1:100,000, or about 1.37 nautical miles per inch."], "explanation": "Sectionals provide the primary VFR planning view of airports, controlled and special-use airspace, obstructions, navigation aids, and terrain.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "AIM Chapter 9 — Sectional Aeronautical Charts", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap9_section_1.html"}},
  {"id": 145, "category": "Airspace & Charts", "difficulty": "Foundation", "question": "What is the scale of a VFR Terminal Area Chart, and why is it useful?", "answer": "1:250,000; its larger scale provides more detail around complex Class B and Class C terminal areas.", "distractors": ["1:500,000; it covers twice as much area and shows more airport detail than a sectional does.", "1:1,000,000; it is most useful for detailed surface navigation inside Class D airspace.", "1:250,000; its smaller scale is useful because it covers a wider area than a sectional does."], "explanation": "At about 3.43 nautical miles per inch, a TAC shows terminal-area detail more clearly than a sectional.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "AIM Chapter 9 — VFR Terminal Area Charts", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap9_section_1.html"}},
  {"id": 146, "category": "Airspace & Charts", "difficulty": "Foundation", "question": "What do blue and magenta airport symbols generally distinguish on a VFR chart?", "answer": "Blue identifies an airport with a control tower; magenta identifies an airport without one.", "distractors": ["Blue identifies an airport without a control tower; magenta identifies an airport with one.", "Blue identifies a paved airport; magenta identifies an unpaved airport, whatever its tower status.", "Blue identifies a public-use airport; magenta identifies a private-use airport, whatever its tower status."], "explanation": "The color does not prove a part-time tower is open at that moment; check its published hours. Airport names and related data normally match the symbol color.", "source": {"label": "FAA Aeronautical Chart Users' Guide", "reference": "VFR chart legend — Airport symbols", "url": "https://www.faa.gov/air_traffic/flight_info/aeronav/digital_products/aero_guide/"}},
  {"id": 147, "category": "Airspace & Charts", "difficulty": "Applied", "question": "Where should a pilot look for airport details that cannot be shown clearly on a sectional, such as operating hours, runway widths, and lighting codes?", "answer": "The applicable FAA Chart Supplement.", "distractors": ["The Remote Pilot Airman Certification Standards.", "The airport’s current Terminal Aerodrome Forecast.", "The UAS Facility Map for that area."], "explanation": "The Chart Supplement expands the chart with airport, communications, weather-source, procedure, and facility details that are impractical to depict graphically.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "AIM Chapter 9 — Chart Supplement", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap9_section_1.html"}},
  {"id": 148, "category": "Airspace & Charts", "difficulty": "Foundation", "question": "Unless a VFR chart states otherwise, what reference is used for its altitudes and times?", "answer": "Altitudes are in feet MSL and times are Coordinated Universal Time (UTC).", "distractors": ["Altitudes are in feet AGL and times are local standard time.", "Altitudes are in feet MSL and times are local standard time.", "Altitudes are in feet AGL and times are Coordinated Universal Time (UTC)."], "explanation": "AGL values and local-time entries are specifically identified when used; the default convention is MSL and UTC.", "source": {"label": "FAA Aeronautical Chart Users' Guide", "reference": "Chart Users' Guide — Introduction and conventions", "url": "https://www.faa.gov/air_traffic/flight_info/aeronav/digital_products/aero_guide/"}},
  {"id": 149, "category": "Airspace & Charts", "difficulty": "Foundation", "question": "How often are FAA Sectional Aeronautical Charts and VFR Terminal Area Charts normally revised?", "answer": "Every 56 days.", "distractors": ["Every 28 days.", "Every 90 days.", "Once each calendar year."], "explanation": "A pilot should confirm the effective date because aeronautical information can change from one edition to the next.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "AIM Chapter 9 — VFR chart revision cycle", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap9_section_1.html"}},
  {"id": 150, "category": "Airspace & Charts", "difficulty": "Foundation", "question": "How far in advance may a pilot submit a LAANC airspace-authorization request?", "answer": "Up to 90 days before the planned flight.", "distractors": ["Up to 30 days before the planned flight.", "Up to 120 days before the planned flight.", "Up to 365 days before the planned flight."], "explanation": "At-or-below-grid requests may be made on the flight date, while above-grid further-coordination requests need at least 72 hours for review.", "source": {"label": "FAA Part 107 Airspace Authorizations", "reference": "LAANC request timing", "url": "https://www.faa.gov/uas/commercial_operators/part_107_airspace_authorizations"}},
  {"id": 151, "category": "Weather", "difficulty": "Applied", "question": "How should a pilot decode the METAR remark \"PK WND 28035/15\"?", "answer": "The peak wind was from 280° true at 35 knots, occurring 15 minutes after the hour.", "distractors": ["The peak wind was from 280° true at 15 knots, occurring 35 minutes after the hour.", "The peak wind was from 280° magnetic at 35 knots, occurring 15 minutes after the hour.", "The prevailing wind was from 280° true at 35 knots and lasted for 15 minutes."], "explanation": "The peak-wind remark reports direction, maximum speed, and the minute when that peak occurred.", "source": {"label": "NWS Aviation Weather Center Product Information", "reference": "METAR remarks — peak wind", "url": "https://aviationweather.gov/help/data/"}},
  {"id": 152, "category": "Weather", "difficulty": "Applied", "question": "What visibility does \"P6SM\" report in a TAF?", "answer": "Prevailing visibility is greater than 6 statute miles.", "distractors": ["Prevailing visibility is exactly 6 statute miles.", "Prevailing visibility is 6 statute miles or more, including exactly 6 miles.", "Prevailing visibility is less than 6 statute miles."], "explanation": "The P prefix means \"more than,\" and SM identifies statute miles.", "source": {"label": "NWS Aviation Weather Center Product Information", "reference": "TAF prevailing-visibility group", "url": "https://aviationweather.gov/help/data/"}},
  {"id": 153, "category": "Weather", "difficulty": "Applied", "question": "How should a remote pilot read the METAR wind group \"VRB04KT\"?", "answer": "The wind direction is variable at 4 knots.", "distractors": ["The wind is from 040° true at a variable speed.", "The wind is calm with occasional gusts to 4 knots.", "The wind is from 040° true, and VRB marks variable visibility."], "explanation": "VRB replaces a specific direction when the wind direction cannot be stated as one representative value.", "source": {"label": "NWS Aviation Weather Center Product Information", "reference": "METAR wind group", "url": "https://aviationweather.gov/help/data/"}},
  {"id": 154, "category": "Weather", "difficulty": "Applied", "question": "What does the weather code \"VCSH\" tell a pilot?", "answer": "Showers are occurring in the vicinity of the reporting station, not necessarily at the station itself.", "distractors": ["Showers are occurring directly over the station itself, not merely in the vicinity.", "Showers are forecast to begin later in the observation period, rather than occurring now.", "Rain is evaporating before it reaches the ground in the vicinity of the station."], "explanation": "VC is a proximity qualifier, so nearby showers may still affect wind, visibility, and the planned operating area.", "source": {"label": "NWS Aviation Weather Center Product Information", "reference": "METAR vicinity and precipitation codes", "url": "https://aviationweather.gov/help/data/"}},
  {"id": 155, "category": "Weather", "difficulty": "Applied", "question": "What does \"VV003\" mean in a METAR sky-condition group?", "answer": "The sky is obscured, with vertical visibility of 300 feet AGL.", "distractors": ["Visibility is varying around 3 statute miles.", "The sky is obscured, with vertical visibility of 3,000 feet.", "A broken cloud layer has a base 300 feet above ground level."], "explanation": "VV is used when an indefinite ceiling prevents normal cloud-layer reporting; the three digits give hundreds of feet AGL.", "source": {"label": "NWS Aviation Weather Center Product Information", "reference": "METAR vertical-visibility group", "url": "https://aviationweather.gov/help/data/"}},
  {"id": 156, "category": "Weather", "difficulty": "Applied", "question": "What does the METAR group \"R27/2400FT\" report?", "answer": "Runway visual range for Runway 27 is 2,400 feet.", "distractors": ["Runway 27 has 2,400 feet of usable pavement remaining.", "Runway visual range for Runway 27 is 24,000 feet.", "Prevailing visibility toward Runway 27 is 2.4 statute miles."], "explanation": "RVR describes visibility along a specific runway; it is not a substitute for evaluating Part 107 flight visibility from the control station.", "source": {"label": "NWS Aviation Weather Center Product Information", "reference": "METAR runway-visual-range group", "url": "https://aviationweather.gov/help/data/"}},
  {"id": 157, "category": "Weather", "difficulty": "Applied", "question": "In METAR remarks, what does \"RAB12\" mean?", "answer": "Rain began 12 minutes after the hour.", "distractors": ["Rain ended 12 minutes after the hour.", "Rain began at 1200 UTC on the day of the report.", "The station measured 0.12 inch of rain."], "explanation": "Remark groups may record when significant precipitation began or ended within the observation hour.", "source": {"label": "NWS Aviation Weather Center Product Information", "reference": "METAR remarks — beginning and ending precipitation", "url": "https://aviationweather.gov/help/data/"}},
  {"id": 158, "category": "Weather", "difficulty": "Foundation", "question": "What does \"AO2\" identify in the remarks of an automated METAR?", "answer": "An automated station equipped with a precipitation discriminator.", "distractors": ["An automated station without a precipitation discriminator.", "A manually observed station augmented by a second observer.", "An automated station with a lightning detector instead of a discriminator."], "explanation": "AO2 is the official code for an automated station with a precipitation discriminator; AO1 identifies one without that equipment.", "source": {"label": "NWS Aviation Weather Center Product Information", "reference": "METAR automated-station type", "url": "https://aviationweather.gov/help/data/"}},
  {"id": 159, "category": "Weather", "difficulty": "Applied", "question": "What sea-level pressure is encoded by the METAR remark \"SLP132\"?", "answer": "1,013.2 hectopascals.", "distractors": ["913.2 hectopascals.", "1,132.0 hectopascals.", "1,031.2 hectopascals."], "explanation": "The three-digit SLP value is decoded to the plausible pressure nearest 1,000 hPa and a decimal is inserted before the last digit.", "source": {"label": "NWS Aviation Weather Center Product Information", "reference": "METAR remarks — sea-level pressure", "url": "https://aviationweather.gov/help/data/"}},
  {"id": 160, "category": "Weather", "difficulty": "Applied", "question": "What probability and time window does \"PROB30 0202/0206\" describe in a TAF?", "answer": "A 30% probability from 0200 through 0600 UTC on the second day of the month.", "distractors": ["A 30% probability from 0200 UTC on the second day through 0600 UTC on the third day.", "A 30% probability from 0002 through 0006 UTC on the second day.", "A forecast that the stated conditions will certainly occur from 0200 through 0600 UTC."], "explanation": "PROB30 expresses the chance of specified conditions, followed by the UTC day-and-hour period when they may occur.", "source": {"label": "NWS Aviation Weather Center Product Information", "reference": "TAF probability group", "url": "https://aviationweather.gov/help/data/"}},
  {"id": 161, "category": "Weather", "difficulty": "Foundation", "question": "What does \"AMD\" mean when it appears after the TAF report type?", "answer": "The terminal forecast has been amended after its original issuance.", "distractors": ["The terminal forecast has been canceled and will not be replaced.", "The transmission was corrected for a typing error, with no change to the forecast.", "The report is an automated METAR rather than a terminal forecast."], "explanation": "An amendment updates the forecast when expected conditions have changed enough to require a revised product.", "source": {"label": "NWS Aviation Weather Center Product Information", "reference": "TAF report modifiers", "url": "https://aviationweather.gov/help/data/"}},
  {"id": 162, "category": "Weather", "difficulty": "Applied", "question": "Decode the TAF wind-shear group \"WS020/24040KT.\"", "answer": "Low-level wind shear is forecast at 2,000 feet AGL, with wind there from 240° true at 40 knots.", "distractors": ["Wind shear is forecast at 200 feet MSL, with wind there from 240° true at 40 knots.", "Low-level wind shear is forecast at 2,000 feet MSL, with wind there from 240° true at 40 knots.", "Wind shear is forecast at 2,400 feet AGL, with wind there from 020° true at 40 knots."], "explanation": "The height follows WS in hundreds of feet, followed by the wind direction and speed at that level.", "source": {"label": "NWS Aviation Weather Center Product Information", "reference": "TAF low-level wind-shear group", "url": "https://aviationweather.gov/help/data/"}},
  {"id": 163, "category": "Weather", "difficulty": "Applied", "question": "What extra information does \"150V220\" add after a METAR wind group?", "answer": "The wind direction varied between 150° and 220° during the observation.", "distractors": ["The wind speed varied between 15 and 22 knots during the observation.", "Runway visual range varied between 1,500 and 2,200 feet.", "The wind was forecast to shift once from 150° to 220° after the observation."], "explanation": "The V group gives the observed directional extremes when the wind varies significantly.", "source": {"label": "NWS Aviation Weather Center Product Information", "reference": "METAR variable wind-direction group", "url": "https://aviationweather.gov/help/data/"}},
  {"id": 164, "category": "Weather", "difficulty": "Scenario", "question": "The temperature and dew point are converging near sunset while winds remain light. What condition should the remote pilot anticipate?", "answer": "An increasing chance of fog or low clouds as the air approaches saturation.", "distractors": ["Rapidly improving visibility as the air dries out and moves farther from saturation.", "Thunderstorms developing overnight as the narrowing spread destabilizes the air.", "Gusty surface wind building after sunset as radiational cooling strengthens."], "explanation": "A shrinking temperature–dew-point spread is a warning sign, especially when nighttime cooling is expected.", "source": {"label": "FAA Aviation Weather Handbook", "reference": "Moisture, saturation, fog, and low-cloud formation", "url": "https://www.faa.gov/sites/faa.gov/files/FAA-H-8083-28B.pdf"}},
  {"id": 165, "category": "Weather", "difficulty": "Scenario", "question": "Strong wind crosses a tree line before reaching the launch area. Where should the crew expect the roughest mechanical turbulence?", "answer": "On the downwind, or leeward, side of the tree line.", "distractors": ["On the upwind side, where the wind first strikes the trees.", "Directly above the treetops, with smooth air just downwind.", "Equally on both sides, since the trees slow all the wind."], "explanation": "Airflow disrupted by buildings, trees, and terrain breaks into eddies that are roughest immediately leeward of the obstruction and weaken farther downwind.", "source": {"label": "FAA Aviation Weather Handbook", "reference": "Mechanical turbulence near surface obstructions", "url": "https://www.faa.gov/sites/faa.gov/files/FAA-H-8083-28B.pdf"}},
  {"id": 166, "category": "Weather", "difficulty": "Scenario", "question": "Strong wind is blowing nearly perpendicular to a mountain ridge. What hazard can develop on the ridge's leeward side?", "answer": "Mountain-wave downdrafts and severe rotor turbulence can develop downwind of the ridge.", "distractors": ["A daytime sea breeze and smooth rising air can develop on the leeward side of the ridge.", "Smooth descending air and clearing skies, with little turbulence below the ridge line.", "Heavy precipitation and icing on the leeward slope, with lowering cloud bases."], "explanation": "The airflow may oscillate after crossing the ridge, producing powerful vertical currents even in otherwise clear air.", "source": {"label": "FAA Aviation Weather Handbook", "reference": "Mountain waves and rotor turbulence", "url": "https://www.faa.gov/sites/faa.gov/files/FAA-H-8083-28B.pdf"}},
  {"id": 167, "category": "Weather", "difficulty": "Foundation", "question": "During a typical sunny afternoon, which way does a sea breeze blow?", "answer": "From the cooler water toward the warmer land.", "distractors": ["From the warmer land out toward the cooler water.", "Parallel to the shoreline rather than across it.", "From land to water aloft, leaving the surface wind unchanged."], "explanation": "Land heats faster than water, encouraging rising air over land and an onshore surface flow.", "source": {"label": "FAA Aviation Weather Handbook", "reference": "Local winds — sea breeze", "url": "https://www.faa.gov/sites/faa.gov/files/FAA-H-8083-28B.pdf"}},
  {"id": 168, "category": "Weather", "difficulty": "Foundation", "question": "During a typical clear night, which way does a land breeze blow?", "answer": "From the cooler land toward the relatively warmer water.", "distractors": ["From the relatively warmer water toward the cooler land.", "Along the shoreline, without moving from land to water.", "Upslope from the coastal valleys toward the higher terrain inland."], "explanation": "At night the land cools faster than water, reversing the pressure pattern that creates a daytime sea breeze.", "source": {"label": "FAA Aviation Weather Handbook", "reference": "Local winds — land breeze", "url": "https://www.faa.gov/sites/faa.gov/files/FAA-H-8083-28B.pdf"}},
  {"id": 169, "category": "Weather", "difficulty": "Foundation", "question": "How does surface wind circulate around a high-pressure system in the Northern Hemisphere?", "answer": "Clockwise and outward from the high.", "distractors": ["Counterclockwise and inward toward the high.", "Clockwise and inward toward the high.", "Counterclockwise and outward from the high."], "explanation": "Friction causes surface wind to cross the isobars slightly away from high pressure.", "source": {"label": "FAA Aviation Weather Handbook", "reference": "Northern Hemisphere pressure-system circulation", "url": "https://www.faa.gov/sites/faa.gov/files/FAA-H-8083-28B.pdf"}},
  {"id": 170, "category": "Weather", "difficulty": "Foundation", "question": "How does surface wind circulate around a low-pressure system in the Northern Hemisphere?", "answer": "Counterclockwise and inward toward the low.", "distractors": ["Clockwise and outward from the low.", "Counterclockwise and outward from the low.", "Clockwise and inward toward the low."], "explanation": "Friction weakens the Coriolis balance near the surface, so wind crosses the isobars toward lower pressure.", "source": {"label": "FAA Aviation Weather Handbook", "reference": "Northern Hemisphere pressure-system circulation", "url": "https://www.faa.gov/sites/faa.gov/files/FAA-H-8083-28B.pdf"}},
  {"id": 171, "category": "Weather", "difficulty": "Applied", "question": "What do tightly packed isobars usually indicate about surface wind?", "answer": "A strong pressure gradient and generally stronger wind.", "distractors": ["A weak pressure gradient and generally lighter wind.", "Stable temperatures, but no indication of wind speed.", "A rapid change in wind direction with little change in wind speed."], "explanation": "A larger pressure change across a shorter distance produces a greater force that accelerates the air.", "source": {"label": "FAA Aviation Weather Handbook", "reference": "Pressure-gradient force and isobars", "url": "https://www.faa.gov/sites/faa.gov/files/FAA-H-8083-28B.pdf"}},
  {"id": 172, "category": "Weather", "difficulty": "Applied", "question": "What weather is commonly found ahead of an approaching warm front?", "answer": "Widespread layered clouds, lowering ceilings, and steady precipitation may develop ahead of the front.", "distractors": ["Rapidly clearing skies, gusty surface wind, and drying air may arrive ahead of the front.", "Brief thunderstorms and gusty wind usually occur in a narrow band right at the surface boundary.", "Cloudless skies, unrestricted visibility, and light surface wind typically extend well ahead of the front."], "explanation": "Warm air rises gradually over retreating cooler air, usually producing a broad area of stratiform weather.", "source": {"label": "FAA Aviation Weather Handbook", "reference": "Warm-front structure and weather", "url": "https://www.faa.gov/sites/faa.gov/files/FAA-H-8083-28B.pdf"}},
  {"id": 173, "category": "Weather", "difficulty": "Applied", "question": "Why can a stationary front disrupt drone operations for an extended period?", "answer": "Because the front moves little, clouds, poor visibility, wind shifts, and precipitation can persist over the same area.", "distractors": ["A stationary front disrupts operations because it normally crosses a site faster than either a warm or cold front.", "Because the two air masses mix along the boundary, conditions usually settle within a few hours.", "A stationary front shifts surface pressure, but its clouds and precipitation break up within an hour or two."], "explanation": "Neither air mass is advancing strongly enough to displace the boundary, so its weather may linger.", "source": {"label": "FAA Aviation Weather Handbook", "reference": "Stationary fronts", "url": "https://www.faa.gov/sites/faa.gov/files/FAA-H-8083-28B.pdf"}},
  {"id": 174, "category": "Weather", "difficulty": "Foundation", "question": "What creates an occluded front?", "answer": "A faster-moving cold front overtakes a warm front and lifts the warm air away from the surface.", "distractors": ["A warm front overtakes a slower cold front and forces the cold air away from the surface.", "Two air masses stop moving and remain on opposite sides of a stationary boundary.", "Two cold fronts from separate low-pressure systems merge into a single boundary."], "explanation": "Occlusion combines frontal structures and can produce extensive clouds and precipitation around the low-pressure system.", "source": {"label": "FAA Aviation Weather Handbook", "reference": "Occluded fronts", "url": "https://www.faa.gov/sites/faa.gov/files/FAA-H-8083-28B.pdf"}},
  {"id": 175, "category": "Weather", "difficulty": "Foundation", "question": "What conditions form advection fog?", "answer": "Warm, moist air moves over a colder surface and cools to its dew point.", "distractors": ["The ground cools rapidly beneath clear skies and calm wind overnight.", "Moist air is forced up a mountain slope and cools as it rises.", "Very cold air moves across much warmer water and receives moisture from below."], "explanation": "Unlike radiation fog, advection fog depends on horizontal air movement and can persist with moderate wind.", "source": {"label": "FAA Aviation Weather Handbook", "reference": "Advection fog", "url": "https://www.faa.gov/sites/faa.gov/files/FAA-H-8083-28B.pdf"}},
  {"id": 176, "category": "Airport & Radio", "difficulty": "Foundation", "question": "What is the reciprocal runway number for Runway 09?", "answer": "Runway 27.", "distractors": ["Runway 18.", "Runway 36.", "Runway 09, the same designator used from both ends."], "explanation": "Opposite runway ends differ by 180°, so 090° becomes 270° and the designator changes from 09 to 27.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "Runway designators", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap2_section_3.html"}},
  {"id": 177, "category": "Airport & Radio", "difficulty": "Foundation", "question": "What do the letters L, C, and R mean after runway numbers?", "answer": "They identify the left, center, and right runways in a parallel-runway group.", "distractors": ["The letters L, C, and R identify low-, category-, and regional-intensity runway lighting systems.", "The letters L, C, and R identify loose-, compacted-, and rigid-surface runway construction.", "The letters L, C, and R identify the landing, crossing, and rollout portions of one runway."], "explanation": "The letters distinguish runway surfaces that otherwise share the same magnetic-direction number.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "Parallel-runway designators", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap2_section_3.html"}},
  {"id": 178, "category": "Airport & Radio", "difficulty": "Applied", "question": "When landing from the displaced-threshold end of a runway, may an aircraft touch down on the pavement ahead of the white threshold bar?", "answer": "No; landing must begin at or beyond the displaced threshold.", "distractors": ["Yes; the pavement ahead of the bar counts as usable landing distance, so touchdown may begin about 500 feet before it.", "Yes; touchdown ahead of the bar is permitted as long as the landing occurs in daylight.", "Yes; an ATC landing clearance extends the usable touchdown area to the pavement ahead of the bar."], "explanation": "The pavement before the bar may be used for takeoff in either direction and for landing rollout from the opposite direction, but not for touchdown from the displaced-threshold end.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "Displaced-threshold markings", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap2_section_3.html"}},
  {"id": 179, "category": "Airport & Radio", "difficulty": "Foundation", "question": "What do large yellow chevrons on pavement aligned with a runway mean?", "answer": "That pavement is unusable for landing, takeoff, and taxiing.", "distractors": ["Large yellow chevrons mark a displaced threshold where touchdown is permitted after receiving clearance.", "Large yellow chevrons mark a taxiway shoulder that aircraft may use at reduced speed.", "Large yellow chevrons identify a closed runway that may still be used for taxiing."], "explanation": "Chevrons mark blast pads, stopways, or other paved areas that are not part of the usable movement surface.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "Runway chevrons", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap2_section_3.html"}},
  {"id": 180, "category": "Airport & Radio", "difficulty": "Foundation", "question": "Which colors distinguish standard runway markings from taxiway markings?", "answer": "Runway markings are white, while taxiway and holding-position markings are yellow.", "distractors": ["Runway markings are yellow, while taxiway and holding-position markings are white.", "Runway and taxiway markings are both yellow, distinguished from each other by line width.", "Runway markings are red, while taxiway and holding-position markings are white."], "explanation": "The color convention helps pilots identify the type and purpose of a paved movement area.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "Airport pavement-marking colors", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap2_section_3.html"}},
  {"id": 181, "category": "Airport & Radio", "difficulty": "Applied", "question": "Approaching a runway holding-position marking from the solid-line side, where must an aircraft stop?", "answer": "Stop before the solid lines. At a towered airport, cross only with ATC clearance; at a non-towered airport, cross only after ensuring adequate separation.", "distractors": ["The aircraft must cross the solid lines and stop immediately before the dashed lines.", "The aircraft may cross the marking without clearance whenever normal radio communication is available.", "The aircraft must hold short when approaching from the dashed-line side; from the solid-line side it may continue without stopping."], "explanation": "No part of the aircraft may extend beyond the marking while holding; non-towered crossing requires separation from aircraft, vehicles, and pedestrians.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "Runway holding-position markings", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap2_section_3.html"}},
  {"id": 182, "category": "Airport & Radio", "difficulty": "Foundation", "question": "What do blue lights identify at an airport at night?", "answer": "Taxiway edges.", "distractors": ["Runway edges.", "Taxiway centerlines.", "The lighted threshold at a runway's approach end."], "explanation": "Blue edge lights distinguish taxiways from runways and other paved areas.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "Taxiway edge lights", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap2_section_1.html"}},
  {"id": 183, "category": "Airport & Radio", "difficulty": "Foundation", "question": "What do steady green lights along a paved route identify?", "answer": "A taxiway centerline.", "distractors": ["A runway centerline.", "Taxiway edges.", "The approach light system leading to a runway threshold."], "explanation": "Green centerline lights help aircraft remain aligned on taxiways in darkness or reduced visibility.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "Taxiway centerline lights", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap2_section_1.html"}},
  {"id": 184, "category": "Airport & Radio", "difficulty": "Applied", "question": "What do yellow runway edge lights near the far end of an instrument runway warn a pilot about?", "answer": "The aircraft is entering the runway’s caution zone and approaching the runway end.", "distractors": ["Yellow runway edge lights warn that the aircraft is approaching a displaced threshold at the runway's beginning.", "Yellow runway edge lights identify an upcoming taxiway intersection where turns are permitted.", "Yellow runway edge lights indicate that the runway ahead is closed and must be exited at the next taxiway."], "explanation": "On instrument runways, edge lights are yellow for the last 2,000 feet or half the runway length, whichever is less.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "Runway edge-light caution zone", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap2_section_1.html"}},
  {"id": 185, "category": "Airport & Radio", "difficulty": "Applied", "question": "What does a four-light PAPI showing two white and two red lights indicate?", "answer": "The aircraft is on the proper glide path.", "distractors": ["Two white and two red PAPI lights indicate that the aircraft is above the proper glide path.", "Two white and two red PAPI lights indicate that the aircraft is below the proper glide path.", "Two white and two red PAPI lights indicate that the PAPI system is out of service."], "explanation": "More white lights indicate a path above the glide path; more red lights indicate a path below it.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "Precision approach path indicator", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap2_section_1.html"}},
  {"id": 186, "category": "Airport & Radio", "difficulty": "Applied", "question": "What is the purpose of runway end identifier lights (REIL)?", "answer": "They help pilots rapidly identify the approach end of a runway.", "distractors": ["Runway end identifier lights identify the departure end of a runway after takeoff.", "Runway end identifier lights mark the runway centerline throughout its full length.", "Runway end identifier lights provide vertical glide-path guidance during final approach."], "explanation": "A REIL system uses synchronized flashing lights on each side of the runway threshold, making the runway end more conspicuous.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "Runway end identifier lights", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap2_section_1.html"}},
  {"id": 187, "category": "Airport & Radio", "difficulty": "Foundation", "question": "What information does an ATIS broadcast provide?", "answer": "A continuous broadcast of recorded noncontrol terminal information, including current weather, approaches and runways in use, and pertinent notices.", "distractors": ["An ATIS broadcast provides individual takeoff, landing, and taxi clearances to each aircraft.", "An ATIS broadcast is reserved for distress calls and airport emergency coordination.", "An ATIS broadcast provides nationwide en route forecasts but no local airport information."], "explanation": "Pilots use the broadcast to receive common airport information before contacting the controller.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "§ 4-1-13 — Automatic Terminal Information Service", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap4_section_1.html"}},
  {"id": 188, "category": "Airport & Radio", "difficulty": "Foundation", "question": "What is a UNICOM station at a non-towered airport?", "answer": "A nongovernment communication station that may provide airport advisories and services but does not issue ATC clearances.", "distractors": ["A UNICOM station is an FAA air traffic control facility that issues binding taxi and landing clearances.", "A UNICOM station is an automated weather sensor that cannot provide airport services or advisories.", "A UNICOM station is a government-operated frequency dedicated to distress and urgency calls."], "explanation": "UNICOM information can improve awareness, but the pilot remains responsible for traffic avoidance and safe operation.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "§§ 4-1-9 through 4-1-12 — UNICOM communications", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap4_section_1.html"}},
  {"id": 189, "category": "Airport & Radio", "difficulty": "Foundation", "question": "Which VHF frequency is the civil aviation emergency frequency?", "answer": "121.5 MHz.", "distractors": ["122.8 MHz.", "123.0 MHz.", "The civil aviation emergency frequency is 243.0 MHz."], "explanation": "The frequency is monitored for distress and urgency communications; it is not for routine conversation.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "§ 6-3-1 — emergency frequencies", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap6_section_3.html"}},
  {"id": 190, "category": "Airport & Radio", "difficulty": "Applied", "question": "What does a steady red tower light signal mean to an aircraft on the ground?", "answer": "Stop.", "distractors": ["Cleared for takeoff.", "Return to the starting point on the airport.", "Cleared to taxi across the airport surface."], "explanation": "Tower light-gun signals provide standardized visual instructions when normal radio communication is unavailable.", "source": {"label": "FAA Aeronautical Information Manual", "reference": "Airport traffic control tower light-gun signals", "url": "https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap4_section_3.html"}},
  {"id": 191, "category": "Performance & Loading", "difficulty": "Foundation", "question": "In weight-and-balance calculations, what is an item’s arm?", "answer": "Its horizontal distance from the aircraft’s reference datum.", "distractors": ["An item's arm is the item's weight measured at the aircraft reference datum.", "An item's arm is the turning moment created by that item about the datum.", "An item's arm is the allowable center-of-gravity range published for the aircraft."], "explanation": "The datum is the manufacturer-defined reference plane from which arms are measured.", "source": {"label": "FAA Weight & Balance Handbook", "reference": "Weight-and-balance terminology — arm and datum", "url": "https://www.faa.gov/sites/faa.gov/files/2023-09/Weight_Balance_Handbook.pdf"}},
  {"id": 192, "category": "Performance & Loading", "difficulty": "Foundation", "question": "How is an item’s moment calculated for weight and balance?", "answer": "Multiply the item’s weight by its arm.", "distractors": ["Calculate an item's moment by dividing its weight by its arm.", "Calculate an item's moment by adding its weight to its arm.", "Calculate an item's moment by multiplying its arm by the square of its weight."], "explanation": "Moment represents the item’s turning effect about the datum and is commonly expressed in pound-inches.", "source": {"label": "FAA Weight & Balance Handbook", "reference": "Weight-and-balance terminology — moment", "url": "https://www.faa.gov/sites/faa.gov/files/2023-09/Weight_Balance_Handbook.pdf"}},
  {"id": 193, "category": "Performance & Loading", "difficulty": "Foundation", "question": "How is the loaded aircraft’s center of gravity calculated from total weight and total moment?", "answer": "Divide total moment by total weight.", "distractors": ["Calculate the loaded center of gravity by dividing total weight by total moment.", "Calculate the loaded center of gravity by adding total weight and total moment.", "Calculate the loaded center of gravity by taking the arithmetic average of the individual item arms."], "explanation": "The resulting arm must fall within the manufacturer’s approved center-of-gravity limits.", "source": {"label": "FAA Weight & Balance Handbook", "reference": "Center-of-gravity calculation", "url": "https://www.faa.gov/sites/faa.gov/files/2023-09/Weight_Balance_Handbook.pdf"}},
  {"id": 194, "category": "Performance & Loading", "difficulty": "Applied", "question": "A 2-pound payload is mounted at an arm of 12 inches. What moment does it add?", "answer": "It adds 24 pound-inches of moment.", "distractors": ["The payload adds 6 pound-inches of moment.", "The payload adds 14 pound-inches of moment.", "The payload adds 10 pound-inches of moment."], "explanation": "Moment equals weight multiplied by arm: 2 lb × 12 in = 24 lb-in.", "source": {"label": "FAA Weight & Balance Handbook", "reference": "Moment calculation", "url": "https://www.faa.gov/sites/faa.gov/files/2023-09/Weight_Balance_Handbook.pdf"}},
  {"id": 195, "category": "Performance & Loading", "difficulty": "Scenario", "question": "An 8-pound aircraft has a 40 pound-inch moment. A 2-pound payload adds 30 pound-inches. What is the combined center-of-gravity arm?", "answer": "The combined center-of-gravity arm is 7 inches from the datum.", "distractors": ["The combined center-of-gravity arm is 5 inches from the datum.", "The combined center-of-gravity arm is 8.75 inches from the datum.", "The combined center-of-gravity arm is 35 inches from the datum."], "explanation": "Add the moments and weights, then divide: (40 + 30) lb-in ÷ (8 + 2) lb = 7 in.", "source": {"label": "FAA Weight & Balance Handbook", "reference": "Combined center-of-gravity calculation", "url": "https://www.faa.gov/sites/faa.gov/files/2023-09/Weight_Balance_Handbook.pdf"}},
  {"id": 196, "category": "Performance & Loading", "difficulty": "Applied", "question": "If a payload’s weight stays the same but it is moved farther from the datum, what happens to its moment?", "answer": "The magnitude of its moment increases in direct proportion to its distance from the datum; the sign depends on which side of the datum the payload is located.", "distractors": ["Its moment becomes more positive in proportion to the greater arm, whether the payload moves forward or aft of the datum.", "Its moment stays the same, because moment depends on the item's weight rather than on where the item is mounted.", "Its moment falls toward zero as the arm grows, because distance from the datum reduces the item's leverage."], "explanation": "Moment equals weight times signed arm. Greater distance increases leverage, while a forward or negative arm produces a more-negative moment.", "source": {"label": "FAA Weight & Balance Handbook", "reference": "Effect of changing an item’s arm", "url": "https://www.faa.gov/sites/faa.gov/files/2023-09/Weight_Balance_Handbook.pdf"}},
  {"id": 197, "category": "Performance & Loading", "difficulty": "Applied", "question": "How does increasing weight affect the stall speed of a fixed-wing small UAS?", "answer": "It increases the stall speed.", "distractors": ["Increasing weight decreases the stall speed of a fixed-wing small UAS.", "Increasing weight has no effect on stall speed if the wing configuration remains unchanged.", "Increasing weight raises the stall speed in a banked turn but leaves the wings-level stall speed unchanged."], "explanation": "A heavier fixed-wing aircraft must produce more lift; at the same configuration and load factor, it reaches the critical angle of attack at a higher airspeed.", "source": {"label": "FAA Pilot’s Handbook of Aeronautical Knowledge", "reference": "Weight, lift requirements, and stall speed", "url": "https://www.faa.gov/regulations_policies/handbooks_manuals/aviation/phak"}},
  {"id": 198, "category": "Performance & Loading", "difficulty": "Applied", "question": "What load factor does an aircraft experience in a coordinated, level 60° bank?", "answer": "A load factor of 2 G.", "distractors": ["A load factor of 1 G.", "A load factor of 1.5 G.", "The aircraft experiences a load factor of 3 G in a coordinated, level 60-degree bank."], "explanation": "At 60° of bank, the aircraft must produce lift equal to twice its weight to maintain altitude.", "source": {"label": "FAA Weight & Balance Handbook", "reference": "Bank angle and load factor", "url": "https://www.faa.gov/sites/faa.gov/files/2023-09/Weight_Balance_Handbook.pdf"}},
  {"id": 199, "category": "Performance & Loading", "difficulty": "Scenario", "question": "A drone’s maximum takeoff weight is 8.8 pounds. It weighs 6.2 pounds empty, and required accessories add 0.4 pound. What is the greatest remaining payload allowed by that limit?", "answer": "The remaining payload allowance is 2.2 pounds.", "distractors": ["The greatest remaining payload allowed is 2.6 pounds.", "The greatest remaining payload allowed is 1.8 pounds.", "The greatest remaining payload allowed is 15.4 pounds."], "explanation": "Subtract the configured aircraft weight from the limit: 8.8 − 6.2 − 0.4 = 2.2 pounds.", "source": {"label": "FAA AC 107-2A", "reference": "Aircraft limitations and mission loading", "url": "https://www.faa.gov/regulations_policies/advisory_circulars/index.cfm/go/document.information/documentID/1038977"}},
  {"id": 200, "category": "Performance & Loading", "difficulty": "Scenario", "question": "A battery provides 24 minutes of usable flight time in the planned conditions. If the pilot reserves 25% for contingencies, what is the maximum planned flight time?", "answer": "The planned flight should be no longer than 18 minutes.", "distractors": ["The maximum planned flight time is 6 minutes.", "The maximum planned flight time is 20 minutes.", "The maximum planned flight time is 16 minutes."], "explanation": "A 25% reserve is 6 minutes, leaving 18 minutes for the planned mission; actual limits and reserve policy should be more conservative when conditions warrant.", "source": {"label": "FAA AC 107-2A", "reference": "Available power and contingency reserves", "url": "https://www.faa.gov/regulations_policies/advisory_circulars/index.cfm/go/document.information/documentID/1038977"}},
  {"id": 201, "category": "ADM & Human Factors", "difficulty": "Foundation", "question": "Under current FAA safety-management definitions, how does a hazard differ from risk?", "answer": "A hazard is a condition or object that could foreseeably cause or contribute to an incident or aircraft accident; risk combines the predicted severity and likelihood of the hazard’s potential effect.", "distractors": ["A hazard is the measured likelihood and severity of harm, while risk is the condition that can cause it.", "A hazard is an unsafe event that has already caused an accident, while risk applies to conditions that have not yet produced one.", "A hazard is the numerical score on a risk matrix, while risk is the physical source of danger."], "explanation": "The hazard is the source of a possible adverse effect; risk combines how severe that effect could be with how likely it is.", "source": {"label": "14 CFR § 5.3", "reference": "14 CFR § 5.3 — hazard and risk", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-A/part-5/subpart-A/section-5.3"}},
  {"id": 202, "category": "ADM & Human Factors", "difficulty": "Foundation", "question": "What is the first step in a small-UAS safety risk assessment?", "answer": "Identify the hazards associated with the aircraft, crew, environment, and planned operation.", "distractors": ["The first step is to assign every possible event a numerical risk score.", "The first step is to select mitigations before identifying what could go wrong.", "The first step is to launch under controlled conditions and use the results as the baseline assessment."], "explanation": "A risk rating is meaningful only after the crew states what could go wrong and why.", "source": {"label": "FAA AC 107-2A", "reference": "Appendix A, ¶ A.2.4 — Developing Risk Assessment Skills", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 203, "category": "ADM & Human Factors", "difficulty": "Foundation", "question": "Which two factors are combined to assign a risk level to an identified hazard?", "answer": "The likelihood that the hazard will occur and the severity of its consequences.", "distractors": ["A risk level combines the duration of exposure with the time available for recovery.", "A risk level combines the mission's financial cost with its schedule priority.", "A risk level combines hazard detectability with the pilot's confidence in the mission."], "explanation": "A risk matrix combines probability and consequence instead of treating every hazard as equally urgent.", "source": {"label": "FAA Risk Management Handbook", "reference": "Chapter 4 — Using a Risk Assessment Matrix", "url": "https://www.faa.gov/sites/faa.gov/files/2022-06/risk_management_handbook_2A.pdf"}},
  {"id": 204, "category": "ADM & Human Factors", "difficulty": "Applied", "question": "When a pilot is unsure between two likelihood or severity ratings, which rating should be used?", "answer": "Use the more conservative rating, which places the hazard at the higher risk level.", "distractors": ["Use the less conservative rating so one uncertain factor does not cancel the mission.", "Average the two ratings and round the result down to the lower risk level.", "Repeat the assessment until both ratings fall into the same lower category."], "explanation": "Optimistic inputs can hide risk; the FAA handbook advises conservative parameters when the assessment is uncertain.", "source": {"label": "FAA Risk Management Handbook", "reference": "Chapter 4 — Risk Matrix Errors: Accuracy", "url": "https://www.faa.gov/sites/faa.gov/files/2022-06/risk_management_handbook_2A.pdf"}},
  {"id": 205, "category": "ADM & Human Factors", "difficulty": "Scenario", "question": "A preflight matrix rates a mission hazard as serious or high. What must happen before launch?", "answer": "Do not launch unless controls reduce the hazard to an acceptable risk level.", "distractors": ["The mission may launch as planned if a visual observer acknowledges the serious or high rating.", "The remote PIC may accept a serious or high rating without mitigation by documenting it before launch.", "The mission should launch and the crew should record whether the serious or high hazard actually occurs."], "explanation": "Serious and high ratings imply a no-go decision until effective mitigation changes the assessment.", "source": {"label": "FAA Risk Management Handbook", "reference": "Chapter 4 — risk-level decisions", "url": "https://www.faa.gov/sites/faa.gov/files/2022-06/risk_management_handbook_2A.pdf"}},
  {"id": 206, "category": "ADM & Human Factors", "difficulty": "Foundation", "question": "What is residual risk?", "answer": "Residual risk is the risk that remains after the planned controls have been applied.", "distractors": ["Residual risk is a new hazard created by a proposed safety control.", "Residual risk is the baseline risk level assigned to a hazard before mitigation is selected.", "Residual risk is the portion of the original risk that the controls have completely eliminated."], "explanation": "A control rarely eliminates every consequence, so the remaining exposure must still be judged acceptable.", "source": {"label": "FAA AC 107-2A", "reference": "Appendix A, ¶ A.4.10 — Residual and Substitute Risk", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 207, "category": "ADM & Human Factors", "difficulty": "Applied", "question": "What is substitute risk when evaluating a proposed safety control?", "answer": "It is a new hazard introduced by the control—potentially making the solution worse than the original problem.", "distractors": ["Substitute risk is the exposure that remains after an effective control has been applied.", "Substitute risk is the initial risk score recorded at the start of the assessment, before a control is chosen.", "Substitute risk is a financial loss transferred from the operator to an insurer."], "explanation": "Every mitigation must be checked both for effectiveness and for new failure paths it creates.", "source": {"label": "FAA AC 107-2A", "reference": "Appendix A, ¶ A.4.10 — Residual and Substitute Risk", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 208, "category": "ADM & Human Factors", "difficulty": "Applied", "question": "How can a risk mitigation lower the overall risk of a hazard?", "answer": "It can reduce the likelihood of the hazard, reduce the severity of the outcome, or reduce both.", "distractors": ["A mitigation lowers risk by reducing the number written in the assessment without changing the hazard.", "A mitigation lowers risk by transferring responsibility for the hazard to another crewmember, even though the likelihood and severity stay the same.", "A mitigation lowers risk by moving the hazard into a different category while leaving the exposure unchanged."], "explanation": "Specific controls should identify which part of the risk they change rather than merely claim that the flight is safer.", "source": {"label": "FAA AC 107-2A", "reference": "Appendix A, ¶ A.4.4 — Formulating Mitigations", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 209, "category": "ADM & Human Factors", "difficulty": "Applied", "question": "Why should a crew identify the root cause of a hazard instead of relying only on its risk score?", "answer": "The root cause shows what must be changed to create an effective risk control.", "distractors": ["The numerical risk score already identifies the needed control, so finding the root cause adds no useful information.", "The crew should control the highest-rated symptom even when that action does not address why the hazard exists.", "Removing the first visible symptom is sufficient even if the underlying condition remains unchanged."], "explanation": "Severity and likelihood describe exposure; root-cause analysis directs the crew toward controls that address why the hazard exists.", "source": {"label": "FAA AC 107-2A", "reference": "Appendix A, ¶ A.4.7 — Reducing Risk", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 210, "category": "ADM & Human Factors", "difficulty": "Applied", "question": "Why should a remote pilot establish personal minimums before accepting a mission?", "answer": "They create predetermined limits based on the pilot’s experience, proficiency, health, and tolerance for risk.", "distractors": ["Personal minimums replace Part 107 limits whenever the pilot has more restrictive preferences.", "Personal minimums provide the airspace authorization needed to operate in controlled airspace.", "Personal minimums remove the residual risk of a mission once the pilot accepts it."], "explanation": "Limits chosen before schedule or customer pressure appears are less likely to be weakened by a desire to complete the job.", "source": {"label": "FAA Remote Pilot Study Guide", "reference": "Chapter 10 — PAVE and personal minimums", "url": "https://www.faa.gov/sites/faa.gov/files/regulations_policies/handbooks_manuals/aviation/remote_pilot_study_guide.pdf"}},
  {"id": 211, "category": "ADM & Human Factors", "difficulty": "Applied", "question": "What should a mission briefing define about conditions that would make the flight unsafe to continue?", "answer": "It should define clear stop or discontinuation criteria and identify who will make and execute the decision.", "distractors": ["A mission briefing should cover the planned route and payload settings, leaving the decision to stop to in-flight judgment.", "A mission briefing should define the customer's delivery deadline as the trigger for discontinuing the flight.", "A mission briefing should define an exact launch time but avoid assigning authority to stop the flight."], "explanation": "Predefined triggers prevent hesitation and debate after the crew is already under pressure.", "source": {"label": "FAA AC 107-2A", "reference": "Appendix A, ¶ A.4.4 — Formulating Mitigations", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 212, "category": "ADM & Human Factors", "difficulty": "Scenario", "question": "The wind, pedestrian activity, and crew workload all increase during a flight. What should the remote PIC do with the original risk assessment?", "answer": "Reassess it using the current conditions and change, pause, or end the operation if the risk is no longer acceptable.", "distractors": ["The remote PIC should keep the original assessment because changing it in flight would make the preflight matrix invalid.", "The remote PIC should ignore the increases unless a published Part 107 limit has already been exceeded.", "The remote PIC should wait until the post-flight debrief to decide whether the increased hazards were acceptable."], "explanation": "A preflight score becomes obsolete when hazards change; risk management continues throughout the flight.", "source": {"label": "FAA AC 107-2A", "reference": "Appendix A, ¶ A.4.1 — In-Flight Mitigations", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 213, "category": "ADM & Human Factors", "difficulty": "Applied", "question": "What two actions does FAA guidance recommend after a flight to improve future risk decisions?", "answer": "Conduct a thorough debrief and capture lessons learned and recommendations.", "distractors": ["After flight, the crew should discard the original assessment and avoid recording unexpected events.", "After flight, the crew should log flight time and battery cycles, because lessons learned are captured during preflight planning rather than afterward.", "After flight, the crew should immediately repeat the mission before conditions change so the original assessment remains valid."], "explanation": "Recording what worked, what failed, and what was unexpected converts one mission’s experience into safer future planning.", "source": {"label": "FAA AC 107-2A", "reference": "Appendix A, ¶ A.4.2 — Post-Flight", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 214, "category": "ADM & Human Factors", "difficulty": "Scenario", "question": "One crewmember is simultaneously watching the drone, monitoring traffic, answering bystanders, and tracking battery status. What is the proper CRM response?", "answer": "Reallocate the tasks, add sufficient crewmembers, or pause the operation before the person becomes overloaded.", "distractors": ["The crewmember should keep the current task list, because a mid-flight handoff creates more confusion than the high workload does.", "The crew should remove the visual observer and transfer every monitoring task to the remote PIC.", "The crew should enable more automation and continue without reassessing whether anyone can monitor it safely."], "explanation": "FAA guidance links excessive workload to a greater possibility of an incident or accident.", "source": {"label": "FAA AC 107-2A", "reference": "Appendix A, ¶ A.2.5.3 — Task Management", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 215, "category": "ADM & Human Factors", "difficulty": "Applied", "question": "When should the crew choose and test its communication method?", "answer": "Before flight, using a method everyone can understand that does not create a distraction.", "distractors": ["The crew should choose its communication method during the preflight briefing and then test it once the aircraft is airborne.", "The crew should reserve the chosen method for emergency calls, because routine status reports distract the remote PIC.", "The crew should wait until a communication problem occurs and then select a method while the aircraft remains airborne."], "explanation": "The best method depends on the site, separation, noise, and equipment; discovering that it fails after launch is too late.", "source": {"label": "FAA AC 107-2A", "reference": "Appendix A, ¶ A.2.5.2 — Communication Methods", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 216, "category": "ADM & Human Factors", "difficulty": "Foundation", "question": "What operational information should a visual observer report to the remote PIC?", "answer": "The drone’s location and flight state, nearby aircraft or hazards, and any developing danger to people or property.", "distractors": ["The visual observer should report battery percentage and camera settings, leaving aircraft position and hazards to the remote PIC.", "The visual observer should report forecast weather changes but not nearby aircraft or people on the surface.", "The visual observer should issue air traffic control instructions to nearby aircraft instead of reporting conflicts to the remote PIC."], "explanation": "A useful observer call gives the pilot actionable information, not merely confirmation that the drone is visible.", "source": {"label": "FAA AC 107-2A", "reference": "¶ 5.9.2 — Visual Observer", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 217, "category": "ADM & Human Factors", "difficulty": "Scenario", "question": "Construction equipment unexpectedly blocks the planned recovery route. What crew-coordination step should follow the remote PIC’s revised plan?", "answer": "Brief the crew on the changed conditions, the new flight profile, and each needed adjustment before continuing.", "distractors": ["The remote PIC should change the plan silently so the crew is not distracted by another briefing.", "The visual observer should continue following the original recovery plan while the remote PIC uses the revised route.", "The crew should continue under the revised plan and record the change in the post-flight debrief instead of briefing it beforehand."], "explanation": "A safe plan change can fail if the observer or control manipulator continues acting on the original briefing.", "source": {"label": "FAA AC 107-2A", "reference": "Appendix A, ¶¶ A.2.5.1 and A.4.1 — changing conditions", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 218, "category": "ADM & Human Factors", "difficulty": "Applied", "question": "What control capability must the remote PIC retain during an automated waypoint mission?", "answer": "The ability to change the route or altitude, avoid a hazard, and command the aircraft to land immediately.", "distractors": ["The remote PIC may let the waypoint sequence run to completion and take manual control after the aircraft returns to the launch point.", "The remote PIC needs the ability to pause the camera payload, while the autopilot keeps authority over the flight path.", "The remote PIC may rely solely on an automatic return-to-home command and does not need to redirect or land the aircraft."], "explanation": "Automation flies programmed inputs, but it does not replace the remote PIC’s authority or responsibility to redirect the aircraft.", "source": {"label": "FAA AC 107-2A", "reference": "¶ 5.2.3 — Automated Operations", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 219, "category": "ADM & Human Factors", "difficulty": "Applied", "question": "What practices help keep complacency and overconfidence from degrading a routine operation?", "answer": "Use the same checklists and structured decision model, and actively verify current conditions even when the mission feels familiar.", "distractors": ["Routine missions should omit written checklists because repetition makes each item automatic.", "The crew should rely on automation to detect changed conditions instead of repeating structured checks.", "The crew should reuse the previous mission's completed checklist and risk assessment whenever the site and aircraft are unchanged."], "explanation": "Repetition can create false confidence; disciplined checks preserve awareness of changes and missed details.", "source": {"label": "FAA AC 107-2A", "reference": "Appendix A, ¶ A.2.6 — Evaluating ADM Skills", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 220, "category": "ADM & Human Factors", "difficulty": "Scenario", "question": "A pilot expects stress from an inexperienced observer, public questions, and unfamiliar site officials. What is the best preflight response?", "answer": "Plan roles, communication, public interaction, and contingencies in advance so those stressors do not consume attention in flight.", "distractors": ["The pilot should wait until launch and improvise roles as each stressor appears.", "The pilot should hand public questions to the visual observer while leaving that observer's flight-monitoring duties unchanged.", "The pilot should shorten the planned flight but leave crew roles, communication, and contingencies undefined."], "explanation": "FAA guidance identifies these as small-UAS stressors and notes that proper planning can reduce or eliminate their effect.", "source": {"label": "FAA AC 107-2A", "reference": "Appendix A, ¶ A.2.3 — Recognize and Cope with Stress", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 221, "category": "ADM & Human Factors", "difficulty": "Scenario", "question": "A remote pilot is acutely fatigued before launch after a night of poor sleep. What is the safe decision?", "answer": "Do not operate; obtain adequate rest before flying.", "distractors": ["The pilot may fly a shorter mission because reducing duration offsets acute fatigue.", "The pilot may continue after asking the visual observer to watch for fatigue-related mistakes.", "The pilot may launch if the aircraft's automation can complete most of the route."], "explanation": "Training and experience do not overcome fatigue’s effects on attention, timing, coordination, and decision-making.", "source": {"label": "FAA Remote Pilot Study Guide", "reference": "Chapter 9 — Acute Fatigue", "url": "https://www.faa.gov/sites/faa.gov/files/regulations_policies/handbooks_manuals/aviation/remote_pilot_study_guide.pdf"}},
  {"id": 222, "category": "ADM & Human Factors", "difficulty": "Applied", "question": "How does chronic fatigue differ from ordinary short-term fatigue, and what action does FAA guidance recommend?", "answer": "Chronic fatigue persists over a long period and is not relieved by proper diet, rest, and sleep; a remote pilot who suspects it should consult a physician.", "distractors": ["Chronic fatigue normally disappears after one short nap and does not require further evaluation.", "Chronic fatigue is the daily circadian low that passes on its own within a few hours.", "Chronic fatigue has the same short duration as ordinary fatigue and is corrected by completing a shorter flight."], "explanation": "Long-term stress or an underlying illness may be involved, so a single good night of sleep is not an adequate remedy.", "source": {"label": "FAA Remote Pilot Study Guide", "reference": "Chapter 9 — Chronic Fatigue", "url": "https://www.faa.gov/sites/faa.gov/files/regulations_policies/handbooks_manuals/aviation/remote_pilot_study_guide.pdf"}},
  {"id": 223, "category": "ADM & Human Factors", "difficulty": "Applied", "question": "Why should a remote pilot hydrate regularly during a hot mission instead of waiting to feel thirsty?", "answer": "Thirst can occur after meaningful dehydration has already reduced physical and mental performance.", "distractors": ["Thirst reliably occurs before dehydration can affect physical or mental performance.", "The pilot should limit fluid intake during the mission so breaks do not interrupt visual line of sight.", "The pilot should use thirst alone to schedule fluids because it precisely tracks current hydration status."], "explanation": "Headache, fatigue, cramps, sleepiness, and dizziness are warning signs; staying ahead of thirst is the safer control.", "source": {"label": "FAA Remote Pilot Study Guide", "reference": "Chapter 9 — Dehydration", "url": "https://www.faa.gov/sites/faa.gov/files/regulations_policies/handbooks_manuals/aviation/remote_pilot_study_guide.pdf"}},
  {"id": 224, "category": "ADM & Human Factors", "difficulty": "Scenario", "question": "Under stress, a pilot becomes dizzy, feels tingling, and realizes they are breathing rapidly. What immediate action addresses likely hyperventilation?", "answer": "Slow the breathing rate and breathe normally; talking aloud can also help restore a normal pattern.", "distractors": ["The pilot should deliberately breathe faster to increase oxygen intake until the tingling stops.", "The pilot should sit down, lower the head, and loosen restrictive clothing until the dizziness passes.", "The pilot should use supplemental oxygen but allow the rapid breathing pattern to continue unchanged."], "explanation": "Hyperventilation removes excessive carbon dioxide and can worsen as anxiety increases, so controlled breathing breaks the cycle.", "source": {"label": "FAA Remote Pilot Study Guide", "reference": "Chapter 9 — Hyperventilation", "url": "https://www.faa.gov/sites/faa.gov/files/regulations_policies/handbooks_manuals/aviation/remote_pilot_study_guide.pdf"}},
  {"id": 225, "category": "ADM & Human Factors", "difficulty": "Scenario", "question": "A pilot has taken a new over-the-counter antihistamine and is unsure whether it causes drowsiness. What does FAA guidance direct the pilot to do?", "answer": "Do not fly; identify the active ingredient, complete at least a 48-hour initial ground trial, and follow any longer medication-specific no-fly interval.", "distractors": ["Over-the-counter medications are presumed safe for flight, so the pilot may launch without testing their effects.", "The pilot may launch if the package carries no aviation warning, even when drowsiness is uncertain.", "Taking half the labeled dose prevents the antihistamine from impairing performance, so the pilot may launch."], "explanation": "Sedating antihistamines are no-go medications; for example, current FAA guidance requires 60 hours after the last dose of diphenhydramine.", "source": {"label": "FAA OTC Medication Guidance", "reference": "48-hour ground trial and antihistamine no-fly guidance", "url": "https://www.faa.gov/ame_guide/media/AME_OTC_medications.pdf"}},
  {"id": 226, "category": "Operations & Safety", "difficulty": "Scenario", "question": "A waiver authorizes BVLOS flight only within a defined corridor. May the operator fly outside that corridor or disregard unrelated Part 107 rules?", "answer": "No. The operator may deviate only from the provisions specified in the waiver and must obey every waiver condition and all other applicable rules.", "distractors": ["Yes; the corridor in a BVLOS waiver is advisory and may be exceeded whenever visual contact is regained.", "Yes; remaining below 400 feet allows the operator to ignore the waiver corridor and unrelated Part 107 rules.", "No. The corridor still binds the operator, though a BVLOS waiver places the rest of the flight under the Part 91 operating rules."], "explanation": "A waiver is limited authorization, not a general exemption from Part 107.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.200(d) — waiver scope and conditions", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 227, "category": "Operations & Safety", "difficulty": "Applied", "question": "Besides weather and airspace, what surface information belongs in the required operating-environment assessment?", "answer": "The locations of people and property on the surface, plus other ground hazards in the operating area.", "distractors": ["Satellite coverage and magnetic-interference forecasts for the planned route and the launch site.", "The medical certificates of each participating crewmember, which the remote PIC verifies before launch.", "The airspace class at the aircraft's planned maximum altitude, plus the ceiling and visibility reported for the site."], "explanation": "The remote PIC must evaluate both airborne conflicts and the consequences of an abnormal landing or falling object.", "source": {"label": "14 CFR Part 107", "reference": "§ 107.49(a)(3)–(4)", "url": "https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-107"}},
  {"id": 228, "category": "Operations & Safety", "difficulty": "Scenario", "question": "A public walkway borders the worksite. What contingency should be planned before launch?", "answer": "Define how the crew will detect and respond if nonparticipants or moving vehicles enter the operational area.", "distractors": ["Wait until pedestrians step into the area and then ask them to leave; the preflight briefing covers crew duties rather than nonparticipant intrusion.", "No intrusion contingency is needed because the walkway is outside the exact takeoff point.", "The crew may continue over people or moving vehicles that enter the area as long as the drone remains below 400 feet."], "explanation": "The plan may use an observer, barriers, a pause call, rerouting, or landing, but the response must be briefed before the intrusion occurs.", "source": {"label": "FAA AC 107-2A", "reference": "¶ 5.11.1 — preflight contingency for people and vehicles", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 229, "category": "Operations & Safety", "difficulty": "Applied", "question": "Which ground locations should be checked for suitability during practical mission planning?", "answer": "The control-station location, takeoff and landing sites, and emergency or alternate landing areas.", "distractors": ["The takeoff and landing sites, leaving control-station suitability for the visual observer to judge once the aircraft is airborne.", "The crew should check nearby airport runways instead of control-station and emergency landing locations.", "Property boundaries and land ownership, since the return-to-home function picks a suitable landing area on its own."], "explanation": "A technically legal route can still be unsafe if the crew lacks a protected place to control, launch, recover, or divert the aircraft.", "source": {"label": "FAA AC 107-2A", "reference": "Appendix E — Sample Preflight Assessment and Inspection Checklist, item 7", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 230, "category": "Operations & Safety", "difficulty": "Scenario", "question": "You are filming near an emergency scene, and the primary landing area might be needed by an EMS helicopter. What should the mission plan include?", "answer": "An alternate landing site—and, if necessary, a predetermined sacrificial area that protects people and manned aircraft.", "distractors": ["Exclusive use of the primary landing area for the drone, held even if an EMS helicopter arrives.", "A hold-and-hover plan that keeps the aircraft airborne until the EMS helicopter departs, in place of an alternate site.", "The nearest public road as a predetermined sacrificial area, since moving traffic clears a landing lane."], "explanation": "Planning the escape before launch prevents low battery and a suddenly occupied recovery area from forcing a dangerous choice.", "source": {"label": "FAA AC 107-2A", "reference": "Appendix A, ¶ A.4.8.1 — alternate landing-site example", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 231, "category": "Operations & Safety", "difficulty": "Scenario", "question": "What potential consequence must a remote PIC understand if GPS is lost during flight?", "answer": "GPS-dependent navigation and position functions may degrade or become unavailable, so the aircraft may not hold position or complete automated navigation as expected.", "distractors": ["The barometric altimeter takes over position hold, so a programmed route continues to fly unchanged until the pilot takes manual control.", "Loss of GPS is limited to the video downlink, because navigation draws its position from the control link's telemetry channel.", "The aircraft automatically falls back to an inertial position solution that is more accurate than GPS, so return-to-home becomes more reliable."], "explanation": "The exact response is aircraft-specific; the pilot must know the manufacturer's loss-of-GPS behavior and prebrief a safe contingency.", "source": {"label": "FAA-S-ACS-10B", "reference": "Area V, Task C, UA.V.C.K4 — loss of GPS signal and consequences", "url": "https://www.faa.gov/sites/faa.gov/files/training_testing/testing/acs/uas_acs.pdf"}},
  {"id": 232, "category": "Operations & Safety", "difficulty": "Applied", "question": "Why can dense Wi-Fi and Bluetooth activity near offices or housing threaten a small-UAS mission?", "answer": "Those signals may share common control bands and interfere with the command link, contributing to loss of control or a flyaway.", "distractors": ["Dense Wi-Fi and Bluetooth activity interferes with the aircraft's GPS receiver, so the risk is position drift rather than lost commands.", "Frequency-hopping control systems retune between channels quickly, so dense congestion costs the mission video quality while the command link holds.", "Wi-Fi and Bluetooth devices transmit near 900 MHz, far from the 2.4 GHz band that small-UAS control links use."], "explanation": "The crew should assess local radio-frequency congestion and follow the aircraft manufacturer's frequency guidance.", "source": {"label": "FAA AC 107-2A", "reference": "Appendix A, Figure A-2 — Wi-Fi/Bluetooth control-link interference", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 233, "category": "Operations & Safety", "difficulty": "Scenario", "question": "A concrete building moves between the control station and the drone. What control-link risk does this create?", "answer": "The barrier can weaken or block the line-of-sight radio-frequency link, causing delayed commands or loss of control.", "distractors": ["The wall reflects the control signal toward the aircraft, so multipath strengthens the link instead of weakening it.", "A concrete building degrades the video downlink while the command uplink's lower data rate keeps it usable behind the structure.", "The structure blocks the aircraft's GPS reception, so the aircraft holds its last commanded heading until it flies clear."], "explanation": "Many 2.4 GHz and 5.8 GHz small-UAS links depend on a clear radio path even when the pilot has planned visual-line-of-sight coverage.", "source": {"label": "FAA AC 107-2A", "reference": "Appendix B, ¶ B.6.1.2 — RF line-of-sight limitations", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 234, "category": "Operations & Safety", "difficulty": "Scenario", "question": "Control inputs become delayed or no longer match aircraft response during a systems check. What should happen next?", "answer": "Stop the flight or avoid launch until the control link has been inspected, tested, and shown to be reliable.", "distractors": ["Continue the mission if the drone remains in visual line of sight despite delayed controls.", "Increase altitude and complete the mission so the command link has a clearer path.", "Reboot the controller while the aircraft remains airborne and resume the route immediately."], "explanation": "Unsynchronized control response can precede a collision, flyaway, or complete loss of control.", "source": {"label": "FAA AC 107-2A", "reference": "Appendix C, Table C-1, condition 8", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 235, "category": "Operations & Safety", "difficulty": "Applied", "question": "What controlled flight check can reveal site-specific interference before committing to the mission route?", "answer": "At low altitude, fly within the expected interference area and recheck control response and stability.", "distractors": ["Fly to the site's maximum legal altitude and test the link at the edge of its advertised range.", "Switch off the controller briefly and verify that the aircraft's failsafe can recover the link.", "Hover behind the largest obstruction until the aircraft is out of sight and check whether commands still work."], "explanation": "The check should remain controlled and conservative; abnormal response means the mission should not continue until resolved.", "source": {"label": "FAA AC 107-2A", "reference": "¶ 7.3.4 and Appendix E — low-altitude control and stability check", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 236, "category": "Operations & Safety", "difficulty": "Foundation", "question": "What conditions can initiate a lithium flight-battery fire?", "answer": "Short circuit, improper charging, extreme heat, crash damage, mishandling, or an internal defect.", "distractors": ["An external ignition source such as an open flame or hot surface, and nothing internal to the pack.", "Charging faults alone, never a pack sitting in storage or already installed in the aircraft.", "Crash damage, but only while the pack is still hot; once it cools to room temperature it is safe."], "explanation": "Lithium-based batteries are highly flammable, so safe handling must cover charging, storage, transport, and post-crash inspection.", "source": {"label": "FAA AC 107-2A", "reference": "Appendix B, ¶ B.5 — Battery Fires", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 237, "category": "Operations & Safety", "difficulty": "Scenario", "question": "A flight battery has a visibly bulging casing. May it be used because it still reaches full indicated charge?", "answer": "No; remove it from service and have its integrity evaluated under manufacturer guidance.", "distractors": ["Yes; the battery may be used if a capacity test and voltage reading remain within limits.", "Yes; discharging the battery to its storage voltage makes a swollen casing safe for another flight.", "No; not until a slow balance-charge cycle restores it, provided the swelling does not increase further."], "explanation": "Bulging can indicate impending abrupt power loss, explosion, fire, or extreme heat; the charge display does not prove safety.", "source": {"label": "FAA AC 107-2A", "reference": "Appendix C, Table C-1, condition 9", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 238, "category": "Operations & Safety", "difficulty": "Scenario", "question": "A battery that once supported 22-minute missions now reaches the same reserve in 13 minutes. What should the operator infer?", "answer": "The battery may be near the end of its service life or damaged and should be inspected before further use.", "distractors": ["The pack is still breaking in, so endurance will improve again after several more charge cycles.", "A firmware update has shortened the displayed mission timer without reducing the battery's actual capacity.", "The battery's internal resistance has fallen, which indicates greater remaining service life."], "explanation": "Diminishing endurance is a reliability warning, not merely a reason to shorten the planned route.", "source": {"label": "FAA AC 107-2A", "reference": "Appendix C, Table C-1, condition 10", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 239, "category": "Operations & Safety", "difficulty": "Applied", "question": "When traveling by passenger aircraft, how must spare lithium flight batteries be carried and protected?", "answer": "Carry them in carry-on baggage, protect each battery individually against short circuit, and follow applicable battery-size and quantity limits.", "distractors": ["Pack spare batteries in checked baggage inside a rigid case, where a fire would stay contained away from the cabin.", "Stack spare batteries together without terminal covers as long as every battery is at storage voltage.", "Carry as many spare batteries as will fit in a cabin bag, since the size and quantity limits cover installed batteries."], "explanation": "Spare lithium batteries are not permitted in checked baggage; original packaging, terminal tape, or a separate protective pouch can prevent short circuits.", "source": {"label": "FAA SAFO 15010", "reference": "Recommended action — individual short-circuit protection", "url": "https://www.faa.gov/sites/faa.gov/files/2022-11/15010_SAFO.pdf"}},
  {"id": 240, "category": "Operations & Safety", "difficulty": "Scenario", "question": "A charger profile does not match the flight-battery type specified by the manufacturer. Should charging continue?", "answer": "No; stop and use the manufacturer-recommended charging method and settings.", "distractors": ["Yes; charging may continue because a modern charger automatically corrects every incompatible profile.", "No; pause until the charge rate is set below 1C, which removes the need to match the manufacturer's profile.", "Yes; continuous visual monitoring eliminates the fire risk from an incompatible charging method."], "explanation": "Improper charging is a recognized cause of lithium-battery ignition, so convenience does not justify an unverified profile.", "source": {"label": "FAA AC 107-2A", "reference": "Appendix B, ¶ B.5 — Battery Fires", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 241, "category": "Operations & Safety", "difficulty": "Scenario", "question": "A preflight inspection reveals a hairline airframe crack or bonded-surface delamination. What is the proper response?", "answer": "Do not fly until the scope, hidden damage, structural integrity, and required repair have been evaluated.", "distractors": ["Cover the crack or delamination with tape and fly if the aircraft passes a power-on check.", "Treat the damage as cosmetic until it grows enough to alter the aircraft's handling.", "Perform a brief hover test and return the aircraft to service without evaluating hidden structural damage."], "explanation": "Small visible damage can extend into a load-bearing structure and compromise the aircraft under vibration or maneuvering loads.", "source": {"label": "FAA AC 107-2A", "reference": "Appendix C, Table C-1, conditions 1 and 2", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 242, "category": "Operations & Safety", "difficulty": "Scenario", "question": "During power-up, the crew smells electrical burning and sees a soot trace near a connector. What should they do?", "answer": "Remove power safely and do not fly until the electrical malfunction and any resulting damage are inspected and corrected.", "distractors": ["Power-cycle the aircraft, and fly if the smell does not return during the second startup.", "Clean off the soot, and fly if the connector still supplies power during a ground test.", "Replace the circuit fuse, and resume operations without investigating what produced the heat and soot."], "explanation": "Odor, soot, or arcing can indicate a fire and heat hazard that may damage structure, performance, or flight duration.", "source": {"label": "FAA AC 107-2A", "reference": "Appendix C, Table C-1, conditions 5 and 6", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 243, "category": "Operations & Safety", "difficulty": "Applied", "question": "What does an unexplained change in propulsion-system sound require before the next flight?", "answer": "Inspect the aircraft—especially motors and propellers—for damage, imbalance, or diminished performance.", "distractors": ["Treat the new sound as normal motor break-in as long as the aircraft still powers up.", "Recalibrate the electronic speed controllers and fly without inspecting the motors or propellers.", "Rely on the flight controller to compensate automatically for the source of the changed sound."], "explanation": "A new sound can be the earliest detectable sign of a mechanical problem even when the aircraft still powers up normally.", "source": {"label": "FAA AC 107-2A", "reference": "Appendix C, Table C-1, condition 7", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 244, "category": "Operations & Safety", "difficulty": "Scenario", "question": "A motor-mount fastener cannot be tightened securely during preflight. What is the correct decision?", "answer": "Replace the fastener that cannot be secured, inspect the affected attachment and structure, and do not fly until structural integrity is confirmed.", "distractors": ["Tighten the damaged fastener past the manufacturer's torque limit, confirm the mount no longer moves by hand, and fly the mission as planned.", "Apply threadlocker to the fastener, let the compound cure, and fly at reduced speed even though the fastener still will not tighten.", "Reduce the payload and fly at a lower airspeed, since lighter loading offsets an insecure motor mount for the rest of the mission."], "explanation": "FAA guidance says to secure loose hardware and replace fasteners that cannot be secured; loose hardware can cause structural failure or dropped objects.", "source": {"label": "FAA AC 107-2A", "reference": "Appendix C, Table C-1, condition 11", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 245, "category": "Operations & Safety", "difficulty": "Foundation", "question": "Which measures may a manufacturer use to schedule periodic small-UAS maintenance or component replacement?", "answer": "Flight hours, operating cycles, calendar time, or another published time-in-service limit.", "distractors": ["Aircraft appearance at each preflight visual check, as judged by the crew on site.", "The remote pilot's certificate currency and the date of the last recurrent training.", "Total client-billable jobs flown since the aircraft was placed in service."], "explanation": "A component can reach a maintenance limit even when it looks serviceable during a quick visual inspection.", "source": {"label": "FAA AC 107-2A", "reference": "Chapter 7, ¶ 7.2.1 — Scheduled Maintenance", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 246, "category": "Operations & Safety", "difficulty": "Scenario", "question": "The manufacturer issues an unscheduled system-software update to correct a known flight-control problem. May the operator postpone it and fly?", "answer": "No; the problem must be corrected before flight operations resume.", "distractors": ["Yes; the operator may postpone the corrective update until the next annual inspection.", "Yes; a manufacturer's corrective update is advisory guidance rather than maintenance, so flights within visual line of sight may continue.", "No; the aircraft stays grounded until the FAA separately issues an airworthiness directive adopting the update."], "explanation": "FAA guidance treats a corrective system-software update as unscheduled maintenance when it addresses a safety-related condition.", "source": {"label": "FAA AC 107-2A", "reference": "Chapter 7, ¶ 7.2.2 — Unscheduled Maintenance", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 247, "category": "Operations & Safety", "difficulty": "Applied", "question": "If the manufacturer provides no scheduled maintenance program, what should the operator establish?", "answer": "A documented maintenance protocol that tracks repairs, modifications, replacements, and component time in service.", "distractors": ["A run-to-failure practice that defers maintenance until a component visibly fails in service.", "A generic 100-hour interval applied without regard to the aircraft's or component's service history.", "A total-aircraft-hours log that leaves repairs, modifications, and component time to the manufacturer's records."], "explanation": "Consistent records let the operator build evidence-based intervals instead of waiting for visible failure.", "source": {"label": "FAA AC 107-2A", "reference": "Chapter 7, ¶ 7.2.1.1 — operator-developed maintenance protocol", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 248, "category": "Operations & Safety", "difficulty": "Applied", "question": "What should a post-flight review record about aircraft condition and mission risk controls?", "answer": "Equipment malfunctions or anomalies, whether the mitigations worked, unexpected hazards, and any repairs or revisions needed before the next flight.", "distractors": ["Flight duration, launch coordinates, battery serial numbers, and the crew members present, logged for the operator's flight records.", "The mitigations that performed as briefed and the equipment that operated normally, kept on file for the operator's records.", "A statement that the aircraft returned undamaged, with anomalies and unexpected hazards left for the next preflight briefing to raise."], "explanation": "A structured review catches developing defects and prevents ineffective controls from being reused without correction.", "source": {"label": "FAA AC 107-2A", "reference": "Appendix E — Post-Flight review", "url": "https://www.faa.gov/documentLibrary/media/Advisory_Circular/Editorial_Update_AC_107-2A.pdf"}},
  {"id": 249, "category": "Operations & Safety", "difficulty": "Applied", "question": "What is required before a remote-pilot crewmember may have unescorted access to an airport Security Identification Display Area (SIDA)?", "answer": "Airport authorization, required security checks and training, and airport-issued identification displayed under the airport’s access procedures.", "distractors": ["A Remote Pilot Certificate and a government-issued photo ID, shown at the gate under the airport's own access procedures.", "A visual observer's escort, accepted in place of airport authorization and airport-issued identification.", "Ground access earned by keeping the aircraft below 400 feet, without following the airport's access procedures."], "explanation": "A Remote Pilot Certificate is not a SIDA credential; escorted and unescorted access must follow the airport security program.", "source": {"label": "49 CFR § 1542.205", "reference": "49 CFR § 1542.205 — security of the SIDA", "url": "https://www.ecfr.gov/current/title-49/subtitle-B/chapter-XII/subchapter-C/part-1542/subpart-C/section-1542.205"}},
  {"id": 250, "category": "Operations & Safety", "difficulty": "Scenario", "question": "A client requests a 200-foot-AGL inspection directly over a facility designated as national-security-sensitive. Does staying below 400 feet make the flight permissible?", "answer": "No; designated facility restrictions apply from the ground up to 400 feet AGL unless the operation is specifically authorized.", "distractors": ["Yes; every flight below 400 feet AGL is permissible over a national-security-sensitive facility.", "No; a standard LAANC airspace authorization, not the 400-foot limit, is what clears the facility restriction.", "Yes; written permission from the facility's owner lifts a designated national-security restriction for that flight."], "explanation": "Examples can include designated military sites, national landmarks, and certain critical infrastructure; the pilot must check current restrictions for the location.", "source": {"label": "FAA Critical Infrastructure and Public Venues", "reference": "Designated national-security-sensitive facility restrictions", "url": "https://www.faa.gov/uas/critical_infrastructure"}}
];
